window.PACK={"book":{"id":"diwan-atahiya","title":"ديوان أبو العتاهية","type":"diwan","author":"أبو العتاهية (ت ٢١١هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"9a561f661c44"},"items":[{"id":"diwan-atahiya:1","bookId":"diwan-atahiya","type":"poem","seq":1,"chapter":"البحر: طويل","title":"لعمرك ، ما الدنيا بدار بقاء ؛","page":"","text":"لعمرك ، ما الدنيا بدار بقاء ؛ … كفاك بدار الموت دار فناء\nفلا تعشق الدنيا ، أخي ، فإنما … يرى عاشق الدنيا بجهد بلاء\nحلاوتها ممزوجة بمرارة … وراحتها ممزوجة بعناء\nفلا تمش يوما في ثياب مخيلة … فإنك من طين خلقت وماء\nلقل امرؤ تلقاه لله شاكرا ؛ … وقل امرؤ يرضى له بقضاء\nولله نعماء علينا عظيمة ، … ولله إحسان وفضل عطاء\nوما الدهر يوما واحدا في اختلافه … وما كل أيام الفتى بسواء\nوما هو إلا يوم بؤس وشدة … ويوم سرور مرة ورخاء\nوما كل ما لم أرج أحرم نفعه ؛ … وما كل ما أرجوه أهل رجاء\nأيا عجبا للدهر لا بل لريبه … يخرم ريب الدهر كل إخاء\nوشتت ريب الدهر كل جماعة … وكدر ريب الدهر كل صفاء\nإذا ما خليلي حل في برزخ البلى ، … فحسبي به نأيا وبعد لقاء\nأزور قبور المترفين فلا أرى … بهاء ، وكانوا ، قبل ، أهل هاء\nوكل زمان واصل بصريمة ، … وكل زمان ملطف بجفاء\nيعز دفاع الموت عن كل حيلة … ويعيا بداء الموت كل دواء\nونفس الفتى مسرورة بنمائها … وللنقص تنمو كل ذات نماء\nوكم من مفدى مات لم ير أهله … حبوه ، ولا جادوا له بفداء\nأمامك ، يا نومان ، دار سعادة … يدوم البقا فيها ، ودار شقاء\nخلقت لإحدى الغايتين ، فلا تنم ، … وكن بين خوف منهما ورجاء\nوفي الناس شر لو بدا ما تعاشروا … ولكن كساه الله ثوب غطاء"},{"id":"diwan-atahiya:2","bookId":"diwan-atahiya","type":"poem","seq":2,"chapter":"البحر: متقارب تام","title":"أشد الجهاد جهاد الورى","page":"","text":"أشد الجهاد جهاد الورى … وما كرم المرء إلا التقى\nوأخلاق ذي الفضل معروفة … ببذل الجميل وكف الأذى\nوكل الفكاهات مملولة … وطول التعاشر فيه القلى\nوكل طريف له لذة … وكل تليد سريع البلى\nولا شيء إلا له آفة … ولا شيء إلا له منتهى\nوليس الغنى نشب في يد … ولكن غنى النفس كل الغنى\nوإنا لفي صنع ظاهر … يدل على صانع لا يرى"},{"id":"diwan-atahiya:3","bookId":"diwan-atahiya","type":"poem","seq":3,"chapter":"البحر: طويل","title":"نصبت لنا دون التفكر يا دنيا","page":"","text":"نصبت لنا دون التفكر يا دنيا … أماني يفنى العمر من قبل تفنى\nمتى تنقضي حاجات من ليس واصلا … إلى حاجة ، حتى تكون له أخرى\nلكل امرىء فيما قضى الله خطة … من الأمر ، فيها يستوي العبد والمولى\nوإن أمرءا يسعى لغير نهاية … لمنغمس في لجة الفاقة الكبرى"},{"id":"diwan-atahiya:4","bookId":"diwan-atahiya","type":"poem","seq":4,"chapter":"قصائد","title":"أما من الموت لحي لجا ؟","page":"","text":"أما من الموت لحي لجا ؟ … كل امرىء عليه الفنا\nتبارك الله ، وسبحانه ، … لكل شيء مدة وأنقضا\nيقدر الإنسان في نفسه … أمرا ويأباه عليه القضا\nويرزق الإنسان من حيث لا … يرجو وأحيانا يضل الرجا\nاليأس يحمي للفتى عرضه … والطمع الكاذب داء عيا\nما أزين الحلم لإصحابه … وغاية الحلم تمام التقى\nوالحمد من أربح كسب الفتى … والشكر للمعروف نعم الجزا\nيا آمن الدهر على أهله ، … لكل عيش مدة وانتها\nبينا يرى الإنسان في غبطة … أصبح قد حل عليه البلى\nلا يفخر الناس بأحسابهم … فإنما الناس تراب وما"},{"id":"diwan-atahiya:5","bookId":"diwan-atahiya","type":"poem","seq":5,"chapter":"البحر: مجزوء الكامل","title":"لله أنت على جفائك","page":"","text":"لله أنت على جفائك … ماذا أومل من وفائك\nإني على ما كان منك … لواثق بجبيل رأيك\nفكرت فيما جفوتني ، … فوجدت ذاك لطول نايك\nفرأيت أن أسعى إلي … ك وأن أبادر في لقائك\nحتى أجد بما تغير … ر لي وأخلق من إخائك"},{"id":"diwan-atahiya:6","bookId":"diwan-atahiya","type":"poem","seq":6,"chapter":"البحر: وافر تام","title":"أذل الحرص والطمع الرقابا","page":"","text":"أذل الحرص والطمع الرقابا … وقد يعفو الكريم ، إذا استرابا\nإذا اتضح الصواب فلا تدعه … فإنك قلما ذقت الصوابا\nوجدت له على اللهوات بردا ، … كبرد الماء حين صفا وطابا\nوليس بحاكم من لا يبالي ، … أأخطأ في الحكومة أم أصابا\nوإن لكل تلخيص لوجها ، … وإن لكل مسألة جوابا\nوإن لكل حادثة لوقتا ؛ … وإن لكل ذي عمل حسابا\nوإن لكل مطلع لحدا ، … وإن لكل ذي أجل كتابا\nوكل سلامة تعد المنايا ؛ … وكل عمارة تعد الخرابا\nوكل مملك سيصير يوما ، … وما ملكت يداه معا ترابا\nأبت طرفات كل قرير عين … بها إلا اضطرابا وانقلابا\nكأن محاسن الدنيا سراب … وأي يد تناولت السرابا\nوإن يك منية عجلت بشيء … تسر به فإن لها ذهابا\nفيا عجبا تموت ، وأنت تبني ، … وتتخذ المصانع والقبابا\nأراك وكلما فتحت بابا … من الدنيا فتحت عليك نابا\nألم تر أن غدوة كل يوم … تزيدك من منيتك اقترابا\nوحق لموقن بالموت أن لا … يسوغه الطعام ، ولا الشرابا\nيدبر ما ترى ملك عزيز … به شهدت حوادثه رغابا\nأليس الله في كل قريبا ؟ … بلى ! من حيث ما نودي أجابا\nولم تر سائلا لله أكدى … ولم تر راجيا لله خابا\nرأيت الروح جدب العيش لما … عرفت العيش مخضا ، واحتلابا\nولست بغالب الشهوات حتى … تعد لهن صبرا واحتسابا\nفكل مصيبة عظمت وجلت … تخف إذا رجوت لها ثوابا\nكبرنا أيها الأتراب حتى … كأنا لم نكن حينا شبابا\nوكنا كالغصون إذا تثنت … من الريحان مونعة رطابا\nإلى كم طول صبوتنا بدار ، … رأيت لها اغتصابا واستلابا\nألا ما للكهول وللتصابي ، … إذا ما اغتر مكتهل تصابى\nفزعت إلى خضاب الشيب مني … وإن نصوله فضح الخضابا\nمضى عني الشباب بغير رد … فعند الله احتسب الشبابا\nوما من غاية إلا المنايا ، … لمن خلقت شبيبته وشابا"},{"id":"diwan-atahiya:7","bookId":"diwan-atahiya","type":"poem","seq":7,"chapter":"البحر: طويل","title":"إذا ما خلوت ، الدهر ، يوما ، فلا تقل","page":"","text":"إذا ما خلوت ، الدهر ، يوما ، فلا تقل … خلوت ولكن قل علي رقيب\nولا تحسبن الله يغفل ما مضى … ولا أن ما يخفى عليه يغيب\nلهونا ، لعمر الله ، حتى تتابعت … ذنوب على آثارهن ذنوب\nفيا ليت أن الله يغفر ما مضى ، … ويأذن في توباتنا فنتوب\nإذا ما مضى القرن الذي كنت فيهم … وخلفت في قرن فأنت غريب\nوإن أمرءا قد سار خمسين حجة … إلى منهل من ورده لقريب\nنسيبك من ناجاك بالود قلبه … وليس لمن تحت التراب نسيب\nفأحسن جزاء ما اجتهدت فإنما … بقرضك تجزى والقروض ضروب"},{"id":"diwan-atahiya:8","bookId":"diwan-atahiya","type":"poem","seq":8,"chapter":"البحر: بسيط تام","title":"لكل أمر جرى فيه القضا سبب ،","page":"","text":"لكل أمر جرى فيه القضا سبب ، … والدهر فيه وفي تصريفه عجب\nما الناس إلا مع الدنيا وصاحبها … فكيف ما انقلبت يوما به انقلبوا\nيعظمون أخا الدنيا ، فإن وثبت … عليه يوما بما لا يشتهي وثبوا\nلا يحلبون لحي در لقحته ، … حتى يكون لهم صفو الذي حلبوا"},{"id":"diwan-atahiya:9","bookId":"diwan-atahiya","type":"poem","seq":9,"chapter":"البحر: وافر تام","title":"ألا لله أنت متى تتوب","page":"","text":"ألا لله أنت متى تتوب … وقد صبغت ذوائبك الخطوب\nكأنك لست تعلم أي حث … يحث بك الشروق ، كما الغروب\nألست تراك كل صباح يوم … تقابل وجه نائبة تنوب\nلعمرك ما تهب الريح ، إلا … نعاك مصرحا ذاك الهبوب\nألا لله أنت فتى وكهلا … تلوح على مفارقك الذنوب\nهو الموت الذي لا بد منه ، … فلا يلعب بك الأمل الكذوب\nوكيف تريد أن تدعى حكيما ، … وأنت لكل ما تهوى ركوب\nوتصبح ضاحكا ظهرا لبطن ، … وتذكر ما اجترمت فما تتوب\nأراك تغيب ثم تؤوب يوما ، … وتوشك أن تغيب ولا تؤوب\nأتطلب صاحبا لا عيب فيه … وأي الناس ليس له عيوب\nرأيت الناس صاحبهم قليل ، … وهم ، والله محمود ، ضروب\nولست مسميا بشرا وهوبا … ولكن الإله هو الوهوب\nتحاشى ربنا عن كل نقص ، … وحاشا سائليه بأن يخيبوا"},{"id":"diwan-atahiya:10","bookId":"diwan-atahiya","type":"poem","seq":10,"chapter":"البحر: منسرح","title":"ما استعبد الحرص من له أدب","page":"","text":"ما استعبد الحرص من له أدب … للمرء في الحرص همة عجب\nلله عقل الحريص كيف له ، … في جمع مال ما له أدب\nما زال حرص الحريص يطمعه … في دركه الشيء ، دونه الطلب\nما طاب عيش الحريص قط ولا … فارقه التعس منه والنصب\nالبغي والحرص والهوى فتن … لم ينج عنها عجم ولا عرب\nليس على المرء في قناعته ، … إن هي صحت ، أذى ولا نصب\nمن لم يكن بالكفاف مقتنعا ، … لم تكفه الأرض كلها ذهب\nمن أمكن الشك من عزيمته … لم يزل الرأي منه يضطرب\nمن عرف الدهر لم يزل حذرا … يحذر شداته ويرتقب\nمن لزم الحقد لم يزل كمدا ، … تغرقه ، في بحورها ، الكرب\nالمرء مستأنس بمنزلة ، … تقتل سكانها ، وتستلب\nوالمرء في لهوه وباطله … والموت منه في الكل مقترب\nيا خائف الموت زال عنك صبا … والعجب واللهو منك واللعب\nدارك تنعى إليك ساكنها ، … قصرك تبلي جديده الحقب\nيا جامع المال منذ كان غدا … يأتي على ما جمعته الحرب\nإياك أن تأمن الزمان فما … زال علينا الزمان ينقلب\nإياك والظلم إنه ظلم … إياك والظن إنه كذب\nبينا ترى القوم في مجلتهم … إذ قيل بادوا ، وقيل قد ذهبوا\nإني رأيت الشريف معترفا … مصطبرا للحقوق ، إذ تجب\nوقد عرفت اللئام ليس لهم … عهد ، ولا خلة ، ولا حسب\nاحذر عليك اللئام إنهم … ليس يبالون منك ما ركبوا\nفنصف خلق اللئام مذ خلقوا … ذل ذليل ، ونصفه شغب\nفر من اللؤم واللئام ولا … تدن إليهم فإنهم جرب"},{"id":"diwan-atahiya:11","bookId":"diwan-atahiya","type":"poem","seq":11,"chapter":"البحر: طويل","title":"أيا إخوتي آجالنا تتقرب","page":"","text":"أيا إخوتي آجالنا تتقرب … ونحن مع الأهلين نلهو ونلعب\nأعدد أيامي ، وأحصي حسابها ، … وما غفلتي عما أعد وأحسب\nغدا إنا من ذا اليوم أدنى إلى الفنا … وبعد غد إليه وأقرب"},{"id":"diwan-atahiya:12","bookId":"diwan-atahiya","type":"poem","seq":12,"chapter":"البحر: كامل تام","title":"يا نفس أين أبي ، وأين أبو أبي ،","page":"","text":"يا نفس أين أبي ، وأين أبو أبي ، … وأبوه عدي لا أبا لك واحسبي\nعدي ، فإني قد نظرت ، فلم أجد … بيني وبين أبيك آدم من أب\nأفأنت ترجين السلامة بعدهم ، … هلا هديت لسمت وجه المطلب\nقد مات ما بين الجنين إلى الرضيع … إلى الفطيم إلى الكبير الأشيب\nفإلى متى هذا أراني لاعبا … وأرى المنية إن أتت لم تلعب"},{"id":"diwan-atahiya:13","bookId":"diwan-atahiya","type":"poem","seq":13,"chapter":"البحر: وافر تام","title":"بكيت على الشباب بدمع عيني","page":"","text":"بكيت على الشباب بدمع عيني … فلم يغن البكاء ولا النحيب\nفيا أسفا أسفت على شباب ، … نعاه الشيب والرأس الخضيب\nعريت من الشباب وكنت غضا … كما يعرى من الورق القضيب\nفيا ليت الشباب يعود يوما ، … فأخبره بما فعل المشيب"},{"id":"diwan-atahiya:14","bookId":"diwan-atahiya","type":"poem","seq":14,"chapter":"البحر: وافر تام","title":"لدوا للموت وابنوا للخراب","page":"","text":"لدوا للموت وابنوا للخراب … فكلكم يصير إلى تباب\nلمن نبني ونحن إلى تراب … نصير كما خلقنا من تراب\nألا يا موت ! لم أر منك بدا ، … أتيت وما تحيف وما تحابي\nكأنك قد هجمت على مشيبي ، … كما هجم المشيب على شبابي\nأيا دنياي ! ما لي لا أراني … أسومك منزلا ألا نبا بي\nألا وأراك تبذل ، يا زماني ، … لي الدنيا وتسرع باستلابي\nوإنك يا زمان لذو صروف … وإنك يا زمان لذو انقلاب\nفما لي لست أحلب منك شطرا ، … فأحمد منك عاقبة الحلاب\nوما لي لا ألح عليك ، إلا … بعثت الهم لي من كل باب\nأراك وإن طلبت بكل وجه … كحلم النوم ، أو ظل السحاب\nأو الأمس الذي ولى ذهابا … وليس يعود ، أو لمع السراب\nوهذا الخلق منك على وفاء … وارجلهم جميعا في الركاب\nوموعد كل ذي عمل وسعي … بما أسدى ، غدا دار الثواب\nنقلدت العظام من البرايا … كأني قد أمنت من العقاب\nومهما دمت في الدنيا حريصا ، … فإني لا أفيق إلى الصواب\nسأسأل عن أمور كنت فيها … فما عذري هناك وما جوابي\nبأية حجة أحتج يوم ال … حساب ، إذا دعيت إلى الحساب\nهما أمران يوضح عنهما لي … كتابي ، حين أنظر في كتابي\nفإما أن أخلد في نعيم … وإما أن أحلد في عذابي"},{"id":"diwan-atahiya:15","bookId":"diwan-atahiya","type":"poem","seq":15,"chapter":"البحر: كامل تام","title":"لم لا نبادر ما نراه يفوت","page":"","text":"لم لا نبادر ما نراه يفوت … إذ نحن نعلم أننا سنموت\nمن لم يوال الله والرسل التي … نصحت له ، فوليه الطاغوت\nعلماؤنا منا يرون عجائبا ، … وهم على ما يبصرون سكوت\nتفنيهم الدنيا بوشك زوالها … فجميعهم بغرورها مبهوت\nوبحسب من يسمو إلى الشهوات ما … يكفيه من شهواته ويقوت\nيا برزخ الموتى الذي نزلوا به … فهم رقود في ثراه ، خفوت\nكم فيك ممن كان يوصل حبله … قد صار بعد وحبله مبتوت"},{"id":"diwan-atahiya:16","bookId":"diwan-atahiya","type":"poem","seq":16,"chapter":"البحر: منسرح","title":"كأنني بالديار قد خربت ،","page":"","text":"كأنني بالديار قد خربت ، … وبالدموع الغزار قد سكبت\nفضحت لا بل جرحت ، واجتحت يا … دنيا رجالا عليك قد كلبت\nالموت حق والدار فانية … وكل نفس تجزى بما كسبت\nيا لك من جيفة معفنة … أي امتناع لها إذا طلبت\nظلت عليها الغواة عاكفة … وما تبالي الغواة ما ركبت\nهي التي لم تزل منغصة ، … لا در در الدنيا إذا احتلبت\nما كل ذي حاجة بمدركها … كم من يد لا تنال مأ طلبت\nفي الناس من تسهل المطالب أح … يانا عليه ، وربما صعبت\nوشرة الناس ربما جمحت … وشهوة النفس ربما غلبت\nمن لم يسعه الكفاف مقتنعا ، … ضاقت عليه الدنيا بما رحبت\nوبينما المرء تستقيم له ال … الدنيا على ما اشتهى إذا انقلبت\nما كذبتني عين رأيت بها … الأموات والعين ربما كذبت\nوأي عيش ، والعيش منقطع ؛ … وأي طعم للذة ذهبت\nويح عقول المستعصمين بدار … الذل في أي منشب نشبت\nمن يبرم الانتقاض منها ومن … يخمد نيرانها ، إذا التهبت\nومن يعزيه من مصائبها ؛ … ومن يقيل الدنيا إذا نكبت\nيا رب عين للشر جالبة ، … فتلك عين تجلى بما جلبت\nوالناس في غفلة وقد خلت … الآجال من وقتها واقتربت"},{"id":"diwan-atahiya:17","bookId":"diwan-atahiya","type":"poem","seq":17,"chapter":"البحر: وافر تام","title":"نسيت الموت فيما قد نسيت","page":"","text":"نسيت الموت فيما قد نسيت … كأني لا أرى أحدا يموت\nأليس الموت غاية كل حي ، … فما لي لا أبادر ما يفوت"},{"id":"diwan-atahiya:18","bookId":"diwan-atahiya","type":"poem","seq":18,"chapter":"البحر: رمل تام","title":"من يعش يكبر ومن يكبر يمت","page":"","text":"من يعش يكبر ومن يكبر يمت … والمنايا لا تبالي من أتت\nكم وكم قد درجت ، من قبلنا ، … من قرون وقرون قد مضت\nأيها المغرور ما هذا الصبا ؟ … لو نهيت النفس عنه لانتهت\nأنسيت الموت جهلا والبلى … وسلت نفسك عنه ولهت\nنحن في دار بلاء وأذى ، … وشقاء ، وعناء ، وعنت\nمنزل ما يثبت المرء به … سالما ، إلا قليلا إن ثبت\nبينما الإنسان في الدنيا له … حركات مقلقات ، إذ خفت\nأبت الدنيا على سكانها ، … في البلى والنقص ، إلا ما أبت\nإنما الدنيا متاع ، بلغة ، … كيفما زجيت في الدنيا زجت\nرحم الله امرءا انصف من … نفسه ، إذ قال خيرا ، أو سكت"},{"id":"diwan-atahiya:19","bookId":"diwan-atahiya","type":"poem","seq":19,"chapter":"البحر: كامل تام","title":"لله در ذوي العقول المشعبات ،","page":"","text":"لله در ذوي العقول المشعبات ، … أخذوا جميعا في حديث الترهات\nوأما ورب المسجدين كلاهما … وأما ورب مني ورب الراقصات\nوأما ورب البيت ذي الأستار … والمسعى وزمزم والهدايا المشعرات\nإن الذي خلقت له الدنيا وما … فيها لنا ذل يجل عن الصفات\nفلينظر الرجل اللبيب لنفسه … فجميع ما هو كائن لا بد آت"},{"id":"diwan-atahiya:20","bookId":"diwan-atahiya","type":"poem","seq":20,"chapter":"البحر: طويل","title":"من الناس ميت وهو حي بذكره","page":"","text":"من الناس ميت وهو حي بذكره … وحي سليم وهو في الناس ميت\nفأما الذي قد مات والذكر ناشر … فميت له دين ، به الفضل ينعت\nوأما الذي يمشي ، وقد مات ذكره ، … فأحمق أفنى دينه ، وهو أموت\nوما زال من قومي خطيب وشاعر ، … وحاكم عدل ، فاصل ، متثبت\nسأضرب أمثالا لمن كان عاقلا ، … يسير بها مني روي مبيت\nوحية أرض ليس يرجى سليمها … تراها إلى أعدائه تتفلت"},{"id":"diwan-atahiya:21","bookId":"diwan-atahiya","type":"poem","seq":21,"chapter":"البحر: خفيف تام","title":"قل لليل وللنهار اكتراثي ،","page":"","text":"قل لليل وللنهار اكتراثي ، … وهما دائبان في استحثاثي\nما بقائي على اخترام الليالي ، … ودبيب الساعات بالأحداث\nيا أخي ما أغرنا بالمنايا … في اتخاذ الأثاث بعد الأثاث\nليت شعري ، وكيف أنت ، إذا ما … ولولت باسمك النساء ألرواثي\nليت شعري ، وكيف أنت مسجى … تحت ردم حثاه فوقك حثائي\nليت شعري ، وكيفما حالك في … ما هناك تكون بعد ثلاث\nإن يوما يكون فيه بمال … مرء أدلى به ذوو الميراث\nلحقيق بإن يكون الذي ير … حل عما حوى قليل التراثي\nأيها المستغيث بي حسبك الله … مغيث الأنام من مستغاث\nفلعمري لرب يوم قنوط ، … قد أتى الله بعده بالغياث"},{"id":"diwan-atahiya:22","bookId":"diwan-atahiya","type":"poem","seq":22,"chapter":"البحر: كامل تام","title":"وإذا انقضى هم امرىء فقد انقضى ،","page":"","text":"وإذا انقضى هم امرىء فقد انقضى ، … إن الهموم أشدهن الأحدث"},{"id":"diwan-atahiya:23","bookId":"diwan-atahiya","type":"poem","seq":23,"chapter":"البحر: بسيط تام","title":"الناس في الدين والدنيا ، ذوو درج ،","page":"","text":"الناس في الدين والدنيا ، ذوو درج ، … والمال ما بين موقوف ، ومحتلج\nمن عاش تقضى له يوما لبانته … وللمضايق أبواب من الفرج\nمن ضاق عنك ، فأرض الله واسعة ، … في كل وجه مضيق وجه منفرج\nقد يدرك الراقد الهادي برقدته … وقد يخيب أخو الروحات والدلج\nخير المذاهب في الحاجات أنجحها ، … وأضيق الأمر أقصاه من الفرج\nلقد علمت ، وإن قصرت في عملي ، … أن ابن آدم لا يخلو من الحجج\nأمن تكون تقيا عند ذي حرج … ما يتقي الله إلا كل ذي حرج"},{"id":"diwan-atahiya:24","bookId":"diwan-atahiya","type":"poem","seq":24,"chapter":"البحر: رمل تام","title":"ليس يرجو الله إلا خائف","page":"","text":"ليس يرجو الله إلا خائف … من رجا خاف ومن خاف رجا\nقلما ينجو امروء من فتنة … عجبا ممن نجا كيف نجا\nترغب النفس ، إذا رغبتها ، … وإذا زجيت بالشيء زجا"},{"id":"diwan-atahiya:25","bookId":"diwan-atahiya","type":"poem","seq":25,"chapter":"البحر: مجزوء الكامل","title":"أسلك من الطرق المناهج","page":"","text":"أسلك من الطرق المناهج … واصبر وإن حملت لاعج\nوانبذ همومك أن تضي … ق بها ، فإن لها مخارج\nواقض الحوائج ما استطعت … ت وكن لهم أخيك فارج\nفلخير أيام الفتى ، … يوم قضى فيه الحوائج"},{"id":"diwan-atahiya:26","bookId":"diwan-atahiya","type":"poem","seq":26,"chapter":"البحر: رمل تام","title":"ذهب الحرص بأصحاب الدلج","page":"","text":"ذهب الحرص بأصحاب الدلج … فهم في غمرة ذات لجج\nليس كل الخير يأتي عجلا … إنما الخير حظوظ ودرج\nلا يزال المرء ما عاش له … حاجة في الصدر منه تختلج\nرب أمر قد تضايقت به … ثم يأتي الله منه بالفرج"},{"id":"diwan-atahiya:27","bookId":"diwan-atahiya","type":"poem","seq":27,"chapter":"البحر: طويل","title":"خليلي إن الهم قد يتفرج","page":"","text":"خليلي إن الهم قد يتفرج … ومن كان يبغي الحق ، فالحق أبلج\nوذو الصدق لا يرتاب ، والعدل قائم … على طرقات الحق والشر أعوج\nوأخلاق ذي التقوى وذي البر في الدجى … لهن سراج ، بين عينيه ، مسرج\nونيات أهل الصدق بيض نقية ، … وألسن أهل الصدق لا تتجلج\nوليس لمخلوق على الله حجة ، … وليس له من حجة الله مخرج\nوقد درجت منا قرون كثيرة ، … ونحن سنمضي بعدهن وندرج\nرويدك ، يا ذا القصر في شرفاته ، … فإنك عنها مستخف وتزعج\nوإنك عما اخترته لمبعد … وإنك مما في يديك لمخرج\nألا رب ذي ضيم غدا في كرامة ، … وملك ، وتيجان الخلود متوج\nلعمرك ما الدنيا لدي نفيسة ، … وإن زخرف الغادون فيها وزبرجوا\nوإن كانت الدنيا إلي حبيبة ، … فإني إلى حظي من الدين أحوج"},{"id":"diwan-atahiya:28","bookId":"diwan-atahiya","type":"poem","seq":28,"chapter":"البحر: طويل","title":"تخفف من الدنيا لعلك أن تنجو","page":"","text":"تخفف من الدنيا لعلك أن تنجو … ففي البر والتقوى لك المسلك النهج\nرأيت خراب الدار يحليه لهوها … إذا اجتمع المزمار والطبل والصنج\nألا أيها المغرور هل لك حجة ، … فأنت بها يوم القيامة محتج\nتدير صروف الحادثات ، فإنها … بقلبك منها كل آونة سحج\nولا تحسب الحالات تبقى لإهلها … فقد يستقيم الحال طورا ، ويعوج\nمن استظرف الشيء استلذ بظرفه ، … ومن مل شيئا كان فيه له مج\nإذا لج أهل اللؤم طاشت عقولهم … كذاك لجاجات اللئام إذا لجوا\nتبارك من لم يشف إلا التقى به … ولم يأتلف إلا به النار والثلج"},{"id":"diwan-atahiya:29","bookId":"diwan-atahiya","type":"poem","seq":29,"chapter":"البحر: مجزوء الكامل","title":"الله أكرم يناجى ،","page":"","text":"الله أكرم يناجى ، … والمرء إن راجيت راجى\nوالمرء ليس بمعظم … شيئا يقضي منه حاجا\nكدر الصفاء من الصدي … ق فلا ترى إلا مزاجا\nوإذا الأمور تزاوجت ، … فالصبر أكرمها نتاجا\nوالصدق يعقد فوق رأس … حليفه للبر تاجا\nوالصدق يثقب زنده … في كل ناحية سراجا\nولربما صدع الصفا … ولربما شعب الزجاجا\nيأبى المعلق بالهوى … إلا رواحا وادلاجا\nأرفق فعمرك عود ذي … أود ، رأيت له اعوجاجا\nوالموت يختلج النفو … س وإن سهت عنه اختلاجا\nإجعل معرجك التكر … م ما وجدت لها انعراجا\nيا رب برق شمته … عادت مخيلته عجاجا\nولرب عذب صار بعد … عذوبة ملحا أجاجا\nولرب أخلاق حسان ، … عدن أخلاقا سماجا\nهون عليك مضايق ال … الدنيا تعد سبلا فجاجا\nلا تضجرن لضيقة … يوما فإن لها انفراجا\nمن عاج من شيء إلى … شيء أصابا له معاجا"},{"id":"diwan-atahiya:30","bookId":"diwan-atahiya","type":"poem","seq":30,"chapter":"البحر: طويل","title":"ألم تر أن الحق أبلج لائح","page":"","text":"ألم تر أن الحق أبلج لائح … وأن لحاجات النفوس جوايح\nإذا المرء لم يكفف عن الناس شره … فليس له ، ما عاش ، منهم مصالح\nإذا كف عبد الله عما يضره … وأكثر ذكر الله ، فالعبد صالح\nإذا المرء لم يمدحه حسن فعاله … فليس له ، والحمد لله ، مادح\nإذا ضاق صدر المرء لم يصف عيشه … وما يستطيب العيش إلا المسامح\nوبينا الفتى ، والملهيات يذقنه … جنى اللهو إذ قامت عليه النوائح\nوإن امرأ أصفاك في الله وده ، … وكان على التقوى معينا لناصح\nوإن ألب الناس من كان همه … بما شهدت منه عليه الجوارح"},{"id":"diwan-atahiya:31","bookId":"diwan-atahiya","type":"poem","seq":31,"chapter":"البحر: وافر تام","title":"أؤمل أن أخلد والمنايا","page":"","text":"أؤمل أن أخلد والمنايا … يثبن علي من كل النواحي\nومأ أدري إذا أمسيت حيا … لعلي لا أعيش إلى الصباح"},{"id":"diwan-atahiya:32","bookId":"diwan-atahiya","type":"poem","seq":32,"chapter":"البحر: رمل تام","title":"لاح شيب الرأس مني فاتضح","page":"","text":"لاح شيب الرأس مني فاتضح … بعد لهو وشباب ومرح\nفلهونا وفرحنا ، ثم لم … يدع الموت لذي اللب فرح\nيا بني آدم صونوا دينكم … ينبغي للدين أن لا يطرح\nوأحمدوا الله الذي أكرمكم … بنذير قام فيكم فنصح\nيخطيب فتح الله به … كل خير نلتموه وشرح"},{"id":"diwan-atahiya:33","bookId":"diwan-atahiya","type":"poem","seq":33,"chapter":"البحر: مجزوء الكامل","title":"إني لأكره أن يكو","page":"","text":"إني لأكره أن يكو … ن لفاجر عندي يد\nفتجر محمدتي إلي … ه وليس ممن يحمد"},{"id":"diwan-atahiya:34","bookId":"diwan-atahiya","type":"poem","seq":34,"chapter":"البحر: رجز تام","title":"دعني من ذكر أب وجد","page":"","text":"دعني من ذكر أب وجد … ونسب يعليك سور المجد\nما الفخر إلا في التقى والزهد ، … وطاعة تعطي جنان الخلد\nلا بد من ورد لأهل الورد … إما إلى خجل ، وإما عد"},{"id":"diwan-atahiya:35","bookId":"diwan-atahiya","type":"poem","seq":35,"chapter":"البحر: متقارب تام","title":"ألا إننا كلنا بائد","page":"","text":"ألا إننا كلنا بائد … وأي بني آدم خالد ؟\nوبدءهم كان من ربهم … وكل إلى ربه عائد\nفيا عجبا كيف يعصي الإله … أم كيف يجحده الجاحد\nولله في كل تحريكة … وفي كل تسكينة شاهد\nوفي كل شيء له آية … تدل على أنه الواحد"},{"id":"diwan-atahiya:36","bookId":"diwan-atahiya","type":"poem","seq":36,"chapter":"البحر: طويل","title":"لك الحمد ياذا العرش يا خير معبود","page":"","text":"لك الحمد ياذا العرش يا خير معبود … ويا خير مسؤول ، ويا خير محمود\nشهدنا لك اللهم أن لست محدثا … ولكنك المولى ولست بمجحود\nوأنك معروف ولست بموصوف … وأنك موجود ولست بمجدود\nوأنك رب لا تزال ولم تزل … قريبا بعيدا ، غائبا ، غير مفقود"},{"id":"diwan-atahiya:37","bookId":"diwan-atahiya","type":"poem","seq":37,"chapter":"البحر: منسرح","title":"يا راكب الغي ، غير مرتشد ،","page":"","text":"يا راكب الغي ، غير مرتشد ، … شتان بين الضلال والرشد\nحسبك ما قد أتيت معتمدا ، … فاستغفر الله ثم لا تعد\nيا ذا الذي نقصه زيادته … إن كنت لم تنتقص ، فلم تزد\nما أسرع الليل والنهار بسا … عات قصار ، تأتي على الأمد\nعجبت من آمل وواعظه … الموت فلم يتعظ ولم يكد\nيجري البلى فيها علينا بما … كان جرى قبلنا على لبد\nيا موت يا موت كم أخي ثقة … كلفتني غمض عينه بيدي\nيا موت يا موت قد أضفت إلى … الفلة من ثروة ومن عدد\nيا موت يا موت صحبتنا بك … الشمس ومست كواكب الأسد\nيا موت يا موت لا أراك من … خلق ، جميعا ، تبقي على أحد\nألحمد لله دائما أبدا ، … قد يصف القصد غير مقتصد\nمن يستتر بالهدى يبر ومن … يبغ إلى الله مطلبا يجد\nقل للجليد المنيع لست من ال … الدنيا بذي منعة ولا جلد\nيا صاحب المدة القصيرة لا … تغفل عن الموت قاطع المدد\nدع عنك تقويم من تقومه … وابدأ ، فقوم ما فيك من أود\nقد ملأ الموت كل أرض وما … ينزع من بلدة إلى بلد"},{"id":"diwan-atahiya:38","bookId":"diwan-atahiya","type":"poem","seq":38,"chapter":"البحر: متقارب تام","title":"ألا إن ربي قوي ، مجيد ،","page":"","text":"ألا إن ربي قوي ، مجيد ، … لطيف ، جليل ، غني ، حميد\nرأيت الملوك ، وإن عظمت ، … فإن الملوك لربي عبيد\nتنافس في جمع مال حطام … وكل يزول ، وكل يبيد\nوكم باد جمع أولو قوة ، … وحصن حصين وقصر مشيد\nوليس بباق على الحادثات ، … لشيء من الخلق ركن شديد\nوأي منيع يفوت الفنا ، … إذا كان يبلى الصفا والحديد\nألا إن رأيا ، دعا العبد أن … ينيب إلى الله ، رأي سديد\nفلا تتكثر بدار البلى ، … فإنك فيها وحيد فريد\nأرى الموت دينا له علة … فتلك التي كنت منها تحيد\nتيقظ فإنك في غفلة … يميد بك السكر ، فيمن يميد\nكأنك لم تركيف الفنا ، … وكيف يموت الغلام الرشيد\nوكيف يموت المسن الكبير … وكيف يموت الصغير الوليد\nومن يأمن الدهر في وعده … وللدهر في كل وعد وعيد\nأراك تأمل ، والشيب قد … وأنت بظنك فيها تزيد\nوتنقص في كل تنفيسة ، … وأنك في ظنك قد تزيد"},{"id":"diwan-atahiya:39","bookId":"diwan-atahiya","type":"poem","seq":39,"chapter":"البحر: مجزوء الكامل","title":"أصبحت ، يا دار الأذى ،","page":"","text":"أصبحت ، يا دار الأذى ، … أصفاك ممتلىء قذى\nأين الذين عهدتهم … قطعوا الحياة ، تلذذا\nدرجوا ، غداة رماهم … ريب الزمان ، فأنفذا\nسنصير أيضا مثلهم … عما قليل هكذا\nيا هؤلاء تفكروا … للموت يغذو من غذا"},{"id":"diwan-atahiya:40","bookId":"diwan-atahiya","type":"poem","seq":40,"chapter":"البحر: مجزوء الكامل","title":"عش ما بدا لك سالما ،","page":"","text":"عش ما بدا لك سالما ، … في ظل شاهقة القصور\nيسعى عليك بما اشتهيت … لدى الرواح أو البكور\nفقال حسن ثم ماذا ؟ فقال : فإذا النفوس تقعقعت ، … في ظل حشرجة الصدور\nفهناك تعلم ، موقنا ، … ما كنت إلا في غرور"},{"id":"diwan-atahiya:41","bookId":"diwan-atahiya","type":"poem","seq":41,"chapter":"البحر: طويل","title":"ألا إنما الدنيا عليك حصار","page":"","text":"ألا إنما الدنيا عليك حصار … ينالك فيها ذلة وصغار\nومالك في الدنيا من الكد راحة … ولا لك فيها إن عقلت قرار\nوما عيشها إلا ليال قلائل ، … سراع وأيام تمر قصار\nوما زلت مزموما تقاد إلى البلى ، … يسوقك ليل ، مرة ، ونهار\nوعارية ما في يديك وإنما … يعار لرد ما طلبت يعار"},{"id":"diwan-atahiya:42","bookId":"diwan-atahiya","type":"poem","seq":42,"chapter":"البحر: خفيف تام","title":"إن ذا الموت ما عليه مجير ،","page":"","text":"إن ذا الموت ما عليه مجير ، … يهلك المستجار والمستجير\nإن تكن لست خابرا بالليالي … وبأحداثها فإني خبير\nهن يبلين والبلى نحن فيها … فسواء صغيرنا والكبير\nأيها الطالب الكثير ليغنى … كل من يطلب الكثير فقير\nوأقل القليل يغني ويكفي ، … ليس يغني وليس يكفي الكثير\nكيف تعمى عن الهدى ، كيف تعمى ، … عجبا والهدى سراج منير\nقد أتاك الهدى من الله نصحا … وبه حياك البشير النذير\nومع الله أنت ما دمت حيا … وإلى الله بعد ذاك تصير\nوالمنايا روائح وغواد ، … كل يوم لها سحاب مطير\nلا تغرنك العيون فكم … أعمى تراه وإنه لبصير\nأنا أغنى العباد ما كان لي كن ، … وما كان لي معاش يسير"},{"id":"diwan-atahiya:43","bookId":"diwan-atahiya","type":"poem","seq":43,"chapter":"البحر: منسرح","title":"ما للفتى مانع من القدر","page":"","text":"ما للفتى مانع من القدر … والموت حول الفتى وبالأثر\nبينا الفتى بالصفاء مغتبط … حتى رماه الزمان بالكدر\nسائل عن الأمر لست تعرفه … فكل رشد يأتيك في الخبر\nكم في ليال وفي تقلبها … من عبر للفتى ، ومن فكر\nإن امرأ يأمن الزمان ، وقد … عاين شداته ، لفي غرر\nما أمكن القول بالصواب فقل … واحذر إذا قلت موضع الضرر\nما طيب القول عند سامعه ال … منصت ، إلا لطيب الثمر\nالشيب في عارضيك بارقة … تنهاك عما أرى من الأشر\nما لك مذ كنت لاعبا مرحا ، … تسحب ذيل السفاه والبطر\nتلعب لعب الصغير ، بله ، وقد … عممك الدهر عمة الكبر\nلو كنت للموت خائفا وجلا … أقرحت منك الجفون بالعبر\nطولت منك المنى وأنت من ال … الأيام في قلة وفي قصر\nلله عينان تكذبانك في … ما رأتا من تصرف العبر\nيا عجبا لي ، أقمت في وطن ، … ساكنه كلهم على السفر\nذكرت أهل القبور من ثقتي ، … فانهل دمعي كوابل المطر\nفقل لأهل القبور من ثقة … لست بناسيكم مدى عمري\nيا ساكنا باطن القبور : أما … للواردين القبور من صدر\nما فعل التاركون ملكهم ، … أهل القباب العظام ، والحجر\nهل يبتنون القصور بينكم ، … أم هل لهم من على ومن خطر\nما فعلت منهم الوجوه : أقد … بدد عنها محاسن الصور\nالله في كل حادث ثقتي … والله عزي والله مفتخري\nلست مع الله خائفا أحدا ، … حسبي به عاصما من الأشر"},{"id":"diwan-atahiya:44","bookId":"diwan-atahiya","type":"poem","seq":44,"chapter":"البحر: خفيف تام","title":"رب أمر يسوء ثم يسر","page":"","text":"رب أمر يسوء ثم يسر … وكذاك الأمور : حلو ومر\nوكذاك الأمور تعبر بالنا … س فخطب يمضي وخطب يكر\nما أغر الدنيا لذي اللهو فيها … عجبا للدنيا ، وكيف تغر\nولمكر الدنيا خطاطيف لهو ، … وخطاطيفها إليها تجر\nولقل امرؤ يفارق ما يع … يعتاد إلا وقلبه مقشعر\nوإذا ما رضيت كل قضاء … الله لم تخش أن يصيبك ضر"},{"id":"diwan-atahiya:45","bookId":"diwan-atahiya","type":"poem","seq":45,"chapter":"البحر: منسرح","title":"توق ما تأتيه وما تذر ،","page":"","text":"توق ما تأتيه وما تذر ، … جميع ما أنت فيه معتذر\nما أبعد الشيء منك ما لم يسا … عدك عليه القضاء والقدر"},{"id":"diwan-atahiya:46","bookId":"diwan-atahiya","type":"poem","seq":46,"chapter":"البحر: وافر تام","title":"طلبت المستقر بكل أرض","page":"","text":"طلبت المستقر بكل أرض … فلم أر لي بأرض مستقرا\nأطعت مطامعي فاستعبدتني ، … ولو أني قنعت لكنت حرا"},{"id":"diwan-atahiya:47","bookId":"diwan-atahiya","type":"poem","seq":47,"chapter":"البحر: متقارب تام","title":"أمني تخاف انتشار الحديث","page":"","text":"أمني تخاف انتشار الحديث … وحظي ، في صونه ، أوفر\nولو لم يكن فيه معنى عليك … نظرت لنفسي كما تنظر"},{"id":"diwan-atahiya:48","bookId":"diwan-atahiya","type":"poem","seq":48,"chapter":"البحر: بسيط تام","title":"الموت باب وكل الناس داخله","page":"","text":"الموت باب وكل الناس داخله … يا ليت شعري بعد الباب ما الدار\nالدار جنة خلد إن عملت بما … يرضي الإله ، وإن قصرت ، فالنار"},{"id":"diwan-atahiya:49","bookId":"diwan-atahiya","type":"poem","seq":49,"chapter":"البحر: مجزوء الكامل","title":"أخوي مرا بالقبو","page":"","text":"أخوي مرا بالقبو … ر ، وسلما قبل المسير\nثم ادعوا من عادها … من ماجد قرم فخور\nومسود رحب الفناء … ء أغر كالقمر المنير\nيا من تضمنه المقابر … بر من كبير ، أو صغير"},{"id":"diwan-atahiya:50","bookId":"diwan-atahiya","type":"poem","seq":50,"chapter":"البحر: سريع","title":"ما أسرع الأيام في الشهر","page":"","text":"ما أسرع الأيام في الشهر … وأسرع الأشهر في العمر\nليس لمن ليست له حيلة … موجودة ، خير من الصبر\nفاخط مع الدهر على ما خطا … واجر مع الدهر كما يجري\nمن سابق الدهر كبا كبوة … لم يستقلها من خطى الدهر"},{"id":"diwan-atahiya:51","bookId":"diwan-atahiya","type":"poem","seq":51,"chapter":"البحر: طويل","title":"نو الحكمة يخوض أناس في الكلام ليوجزوا ،","page":"","text":"نو الحكمة يخوض أناس في الكلام ليوجزوا ، … وللصمت في بعض الأحايين أوجز\nفإن كنت عن أن تحسن الصمت عاجزا … فأنت ، عن الإبلاغ في القول ، أعجز"},{"id":"diwan-atahiya:52","bookId":"diwan-atahiya","type":"poem","seq":52,"chapter":"البحر: وافر تام","title":"نسيت منيتي ، وخدعت نفسي ،","page":"","text":"نسيت منيتي ، وخدعت نفسي ، … وطال علي تعميري ، وغرسي\nوكل ثمينة أصبحت أغلي … بها ستباع من بعدي بوكس\nوما أدري ، وإن أملت عمرا ، … لعلي حين أصبح لست أمسي\nوساعة متتي ، لا بد منها ، … تعجل نقلتي ، وتطيل حبسي\nأموت ويكره الأحباب قربي … وتحضر وحشتي ، ويغيب أنسي\nألا يا ساكن البيت الموشى … ستسكنك المنية بطن رمس\nرأيتك تذكر الدنيا كثيرا ، … وكثرة ذكرها للقلب تقسي\nكأنك لا ترى بالخلق نقصا … وأنت تراه كل شروق شمس\nوطالب حاجة أعيا وأكدى … ومدرك حاجة في لين لمس\nألا ولقل ما تلقى شجيا … يسيغ شجاه إلا بالتأسي"},{"id":"diwan-atahiya:53","bookId":"diwan-atahiya","type":"poem","seq":53,"chapter":"البحر: بسيط تام","title":"ما يدفع الموت أرجاء ولا حرس","page":"","text":"ما يدفع الموت أرجاء ولا حرس … ما يغلب الموت لا جن ولا أنس\nما إن دعا الموت أملاكا ولا سوقا … إلا ثناهم إليه الصرع والخلس\nللموت ما تلد الأقوام كلهم … وللبلى كل ما بنوا ، وما غرسوا\nهلا أبادر هذا الموت في مهل … هلا أبادره ما دام لي نفس\nيا خائف الموت لو أمسيت خائفه … كانت دموعك طول الدهر تنبجس\nأما يهولك يوم لا دفاع له … إذ أنت في غمرات الموت تنغمس\nإياك إياك والدنيا لو اجتهدوا … فالموت فيها لخلق الله مفترس\nإن الخلائق في الدنيا لو اجتهدوا … أن يحبسوا عنك هذا الموت ما حبسوا\nإن المنية حوض أنت تكرهه ، … وأنت عمأ قليل فيه منغمس\nما لي رأيت بني الدنيا قد اقتتلوا ، … كأنما هذه الدنيا لهم عرس\nإذا وصفت لهم دنياهم ضحكوا … وإن وصفت لهم أخراهم عبسوا\nما لي رأيت بني الدنيا وإخوتها ، … كأنهم لكلام الله ما درسوا"},{"id":"diwan-atahiya:54","bookId":"diwan-atahiya","type":"poem","seq":54,"chapter":"البحر: طويل","title":"سلام على أهل القبور الدوارس ،","page":"","text":"سلام على أهل القبور الدوارس ، … كأنهم لم يجلسوا في المجالس\nولم يبلغوا من بارد الماء لذة … ولم يطعموا ما بين رطب ويابس\nولم يك منهم ، في الحياة ، منافس … طويل المنى فيها كثير الوساوس\nلقد صرتم في غاية الموت والبلى … وأنتم بها ما بين راج وآئس\nفلو عقل المرء المنافس في الذي … تركتم من الدنيا إذا لم ينافس"},{"id":"diwan-atahiya:55","bookId":"diwan-atahiya","type":"poem","seq":55,"chapter":"البحر: بسيط تام","title":"من نافس الناس لم يسلم من الناس ،","page":"","text":"من نافس الناس لم يسلم من الناس ، … حتى يعض بأنياب وأضراس\nلا بأس بالمرء ما صحت سريرته … ما الناس إلا بأهل العلم والناس\nكاس الألى أخذوا للموت عدته … وما المعدون للدنيا بأكياس\nحتى متى والمنايا لي مخاتلة … يغرني في صروف الدهر وسواسي\nأين الملوك التي حفت مدائنها ، … دون المنايا ، بحجاب وحراس\nلقد نسيت وكأس الموت دائرة … في كف لا غافل عنها ولا ناسي\nلأشربن بكأس الموت منجدلا … يوما كما شرب الماضون بالكاس\nأصبحت ألعب والساعات مسرعة … ينقصن رزقي ويستقصين أنفاسي\nإني لأغتر بالدنيا وأرفعها … من تحت رجلي ، أحيانا ، على راسي\nما استعبد المرء كاستعباد مطمعه … ولا تسلى بمثل الصبر والياس"},{"id":"diwan-atahiya:56","bookId":"diwan-atahiya","type":"poem","seq":56,"chapter":"البحر: وافر تام","title":"ألا للموت كأس أي كاس","page":"","text":"ألا للموت كأس أي كاس … وأنت لكأسه لا بد حاس\nإلى كم ، والمعاد إلى قريب ، … تذكر بالمعاد وأنت ناس\nوكم من عبرة أصبحت فيها … يلين لها الحديد وأنت قاس\nبأي قوى تظنك ليس تبلى … وقد بليت على الزمن الرواسي\nوما كل الظنون تكون حقا … ولا كل الصواب على القياس\nوكل مخيلة رفعت لعين … لها وجهان من طمع وياس\nوفي حسن السريرة كل أنس ؛ … وفي خبث السريرة كل باس\nولم يك منية ، حسدا وبغيا ، … لينجو منهما رأسا براس\nوما شيء بأخلق أن تراه … قليلا من أخي ثقة ، مؤاس\nوما تنفك من دول تراها ، … تنقل من أناس في أناس"},{"id":"diwan-atahiya:57","bookId":"diwan-atahiya","type":"poem","seq":57,"chapter":"البحر: هزج","title":"لقد هان على الناس","page":"","text":"لقد هان على الناس … من احتاج إلى الناس\nفصن نفسك عما كا … ن عند الناس بالياس\nفكم من مشرب يشفي ال … صدى من مشرب قاس\nوثقل الحق أحيانا … كمثل الجبل الراسي"},{"id":"diwan-atahiya:58","bookId":"diwan-atahiya","type":"poem","seq":58,"chapter":"البحر: طويل","title":"خذ الناس أو دع إنما الناس بالناس","page":"","text":"خذ الناس أو دع إنما الناس بالناس … ولا بد في الدنيا من الناس للناس\nولست بناس ذكر شيء تريده … وما لم ترد شيئا ، فأنت له الناسي\nمن الظلم تشغيب أمرئ ليس منصف … وما بامرىء لم يظلم الناس من باس\nألا قل ما ينجو ضمير من المنى … وفيه له منهن شعبة وسواس\nولم ينج مخلوقا من الموت حيلة … ولو كان في حصن وثيق وحراس\nوما المرء إلا صورة من سلالة ، … يشيب ويفنى بين لمح وأنفاس\nتدير يد الدنيا الردى بين أهلها ، … كأنهم شرب قعود على كاس\nكفى بدفاع الله عن كل خائف ، … وإن كان فيها بين ناب وأضراس\nوكم هالك بالشيء فيما يكده … وكم من معافى حز من جبل راس"},{"id":"diwan-atahiya:59","bookId":"diwan-atahiya","type":"poem","seq":59,"chapter":"البحر: بسيط تام","title":"إن استتم من الدنيا لك اليأس","page":"","text":"إن استتم من الدنيا لك اليأس … فلن يغمك لا موت ، ولا ناس\nالله أصدق والآمال كاذبة … وكل هذي المنى في القلب وسواس\nوالخير أجمع إن صح المراد له … ما يصنع الله لا ما يصنع الناس"},{"id":"diwan-atahiya:60","bookId":"diwan-atahiya","type":"poem","seq":60,"chapter":"البحر: طويل","title":"إذا المرء لم يربع على نفسه طاشا","page":"","text":"إذا المرء لم يربع على نفسه طاشا … سيرمى بقوس الجهل من كان طياشا\nفلا يأمنن المرء سوءا يغره ، … إذا جالس المعروف بالسوء أو ماشى\nوليس بعيدا كل ما هو كائن ، … وما أقرب الأمر البطيء لمن عاشا"},{"id":"diwan-atahiya:61","bookId":"diwan-atahiya","type":"poem","seq":61,"chapter":"البحر: خفيف تام","title":"زاد حبي لقرب أهل المعاصي","page":"","text":"زاد حبي لقرب أهل المعاصي … دون أهل الحديث والإخلاص\nكيف أغتر بالحياة ، وعمري … ساعة بعد ساعة في انتقاص ؟"},{"id":"diwan-atahiya:62","bookId":"diwan-atahiya","type":"poem","seq":62,"chapter":"البحر: كامل تام","title":"كل على الدنيا له حرص","page":"","text":"كل على الدنيا له حرص … والحادثات أناتها غفص\nتبغي من الدنيا زيادتها ، … وزيادتي فيها هي النقص\nوكأن من واروه في جدث … لم يبد منه لناظر شخص\nليد المنية في تلطفها ، … عن ذخر كل شفيقة ، فحص"},{"id":"diwan-atahiya:63","bookId":"diwan-atahiya","type":"poem","seq":63,"chapter":"البحر: خفيف تام","title":"إن عيشا يكون آخره المو","page":"","text":"إن عيشا يكون آخره المو … ت لعيش معجل التنغيص"},{"id":"diwan-atahiya:64","bookId":"diwan-atahiya","type":"poem","seq":64,"chapter":"البحر: بسيط تام","title":"ننسى المنايا على أنا لها غرض ،","page":"","text":"ننسى المنايا على أنا لها غرض ، … فكم أناس رأيناهم قد انقرضوا\nإنا لنرجو أمورا نستعد لها ، … والموت دون الذي نرجو لمعترض\nلله در بني الدنيا لقد غبنوا … فيما اطمانوا به من جهلهم ورضوا\nما أربح الله في الدنيا تجارة إن … سان يرى أنها من نفسه عوض\nفليست الدار دارا لا ترى أحدا … من أهلها ، ناصحا ، لم يعده غرض\nما بال من عرف الدنيا الدنية لا … ينكف عن غرض الدنيا وينقبض\nتصح أقوال أقوام بوصفهم ، … وفي القلوب إذا كشفتها مرض\nوالناس في غفلة عما يراد بهم … وكلهم عن جديد الأرض منقرض\nوالحادثات بها الأقدار جارية … والمرء مرتفع فيها ، ومنخفض\nيا ليت شعري وقد جد الرحيل بنا … حتى متى نحن في الغرات نرتكض\nنفس الحكيم إلى الخيرات ساكنة … وقلبه من دواعي الشر منقبض\nاصبر على الحق تستعذب مغبته … والصبر للحق أحيانا له مضض\nوما استربت فكن وقافة حذرا … قد يبرم الأمر أحيانا فينتقض"},{"id":"diwan-atahiya:65","bookId":"diwan-atahiya","type":"poem","seq":65,"chapter":"البحر: كامل تام","title":"اشتد بغي الناس في الأرض","page":"","text":"اشتد بغي الناس في الأرض … وعلو بعضهم على بعض\nدعهم وما اختاروا لأنفسهم … فالله بين عباده يقضي"},{"id":"diwan-atahiya:66","bookId":"diwan-atahiya","type":"poem","seq":66,"chapter":"البحر: طويل","title":"أقول ويقضي الله ما هو قاضي ،","page":"","text":"أقول ويقضي الله ما هو قاضي ، … وإني بتقدير الإله لراضي\nأرى الخلق يمضي واحدا بعد واحد ، … فيا ليتني أدري متى أنا ماض\nكأن لم أكن حيا إذا احتث غاسلي … وأحكم درجي في ثياب بياض"},{"id":"diwan-atahiya:67","bookId":"diwan-atahiya","type":"poem","seq":67,"chapter":"البحر: كامل تام","title":"قلب الزمان سواد رأسك أبيضا","page":"","text":"قلب الزمان سواد رأسك أبيضا … ونعاك جسمك رقة ، وتقبضا\nنل أي شيء شئت من نوع المنى … فكأن شيئا لم تنله ، إذا انقضى\nوإذا أتى شيء أتى لمضيه ، … وكأنه لم يأت قط إذا مضى\nنبغي من الدنيا الغنى فيزيدنا … فقرا ونطلب أن نصح فنمرضا\nلن يصدق الله المحبة عبده ، … إلا أحب له ومنه وأبغضا\nوالنفس في طلب الخلاص وما لها … من مخلص ، حتى تصير إلى الرضى"},{"id":"diwan-atahiya:68","bookId":"diwan-atahiya","type":"poem","seq":68,"chapter":"البحر: رمل تام","title":"نسأل الله بما يقضي الرضى ،","page":"","text":"نسأل الله بما يقضي الرضى ، … حسبي الله بما شاء قضى\nقد أردنا ، فأبى الله لنا ، … وأراد الله شيئا فمضى\nرب أمر بت قد أبرمته … ثم ما أصبحت إلا فانقضى\nكم وكم من هنة محقورة ، … تركت قوما كثيرا أمرضا\nرب عيش لأناس سلفوا … كان ثم انقرضوا أو قرضا\nعجبا للموت ما أقطعه ، … ما رأينا مات رفضا\nرفض الميت من ساعته ، … وجفاه أهله حين قضى\nشر أيامي هو اليوم الذي … أقبل الدنيا بديني عوضا"},{"id":"diwan-atahiya:69","bookId":"diwan-atahiya","type":"poem","seq":69,"chapter":"البحر: متقارب تام","title":"رضيت لنفسي بغير الرضا","page":"","text":"رضيت لنفسي بغير الرضا … وكل سيجزى بما أقرضا\nبليت بدار رأيت الحكيم … لزهرتها قاصيا مبغضا\nسيمضي الذي هو مستقبل ، … مضي الذي مر بي ، فانقضى\nوإنا لفي منزل لم يزل … نراه حقيقا بأن يرفضا\nقضى الله فيه علينا الفنا … له الحمد شكرا على ما قضى"},{"id":"diwan-atahiya:70","bookId":"diwan-atahiya","type":"poem","seq":70,"chapter":"البحر: بسيط تام","title":"حب الرئاسة أطغى من على الأرض ،","page":"","text":"حب الرئاسة أطغى من على الأرض ، … حتى بغى بعضهم منها على بعض\nفحسبي الله ربي لا شبيه به … وضعت فيه كلا بسطي ، ومنقبضي\nإن القنوع لزاد ، إن رأيت به ، … كنت الغني وكنت الوافر العرض\nما بين ميت وبين الحي من صلة ، … من مات أصبح في بحبوحة الرفض\nالدهر يبرمني طورا وينقضني ، … فما بقائي على الإبرام والنقض\nما زلت مذ كان في الروح منقبضا … يموت ، في كل يوم مر بي ، بعضي"},{"id":"diwan-atahiya:71","bookId":"diwan-atahiya","type":"poem","seq":71,"chapter":"البحر: كامل تام","title":"ماذا يصير إليك يا أرض","page":"","text":"ماذا يصير إليك يا أرض … ممن غزاه اللين ، والخفض\nأبهرت من وافت منيته ، … وكان حب حبيبه بغض\nعجبا لذي أمل يغر به ، … ويقينه بفنائه نقض\nولكل ذي عمل يدين به ، … يوما على ديانه عرض\nيا ذا المقيم بمنزل آشب … ومقام ساكنه به دحض\nما لابن آدم في تصرف ما … يجري به بسط ولا قبض"},{"id":"diwan-atahiya:72","bookId":"diwan-atahiya","type":"poem","seq":72,"chapter":"البحر: طويل","title":"خليلي إن لم يغتفر كل واحد","page":"","text":"خليلي إن لم يغتفر كل واحد … عثار أخيه منكما ، فترافضا\nوما يلبث الحبان ، إن لم يجوزا … كثيرا من المكروه ، أن يتباغضا\nخليلي باب الفضل أن يتواهبا … كما أن باب النقص أن يتقارضا"},{"id":"diwan-atahiya:73","bookId":"diwan-atahiya","type":"poem","seq":73,"chapter":"البحر: كامل تام","title":"حتى متى تصبو ورأسك أشمط","page":"","text":"حتى متى تصبو ورأسك أشمط … أحسبت أن الموت في اسمك يغلط\nأم لست تحسبه عليك مسلطا ، … وبلى ، وربك ، إنه لمسلط\nولقد رأيت الموت يفرس ، تارة ، … جثث الملوك وتارة يتخبط\nفتآلف الخلان مفتقدا لهم … ستشط عمن تألفن ، وتشحط\nوكأنني بك بينهم واهي القوى ، … نصوا ، تقلص بينهم وتبسط\nوكأنني بك بينهم خفق الحشا ، … بالموت في غمراته يتشحط\nوكأنني بك في قميص مدرجا ، … في ريطتين ملفف ، ومخيط\nلا ريطتين كريطتي متنسم … روح الحياة ، ولا القميص مخيط"},{"id":"diwan-atahiya:74","bookId":"diwan-atahiya","type":"poem","seq":74,"chapter":"البحر: طويل","title":"أتجمع مالا لا تقدم بعضه","page":"","text":"أتجمع مالا لا تقدم بعضه … لنفسك ذخرا إن ذا لسقوط\nاتوصي لمن بعد الممات جهالة … وتتركه حيا وأنت بسيط\nنصيبك مما صرت تجمع دائبا … فثوبان من قبطية وحنوط\nكأنك قد جهزت تهدى إلى البلى … لنفسك في أيدي الرجال أطبط"},{"id":"diwan-atahiya:75","bookId":"diwan-atahiya","type":"poem","seq":75,"chapter":"البحر: كامل تام","title":"غلبتك نفسك ، غير متعظه ،","page":"","text":"غلبتك نفسك ، غير متعظه ، … نفس مقرعة بكل عظه\nنفس مصرفة ، مدبرة ، … مطلوبة في النوم واليقظه\nنفس ستطغيها وساوسها ، … إن لم تكن منهن محتفظه\nفالله حسبك لا سواه ومن … راع الرعاة وحافظ الحفظه"},{"id":"diwan-atahiya:76","bookId":"diwan-atahiya","type":"poem","seq":76,"chapter":"البحر: طويل","title":"عليكم سلام الله إني مودع","page":"","text":"عليكم سلام الله إني مودع … وعيناي من مض التفرق تدمع\nفإن نحن عشنا يجمع الله بيننا … وإن نحن متنا ، فالقيامة تجمع\nألم تر ريب الدهر في كل ساعة … له عارض فيه المنية تلمع\nأيا باني الدنيا لغيرك تبتني … ويا جامع الدنيا لغيرك تجمع\nأرى المرء وثابا على كل فرصة … وللمرء يوما لا محالة مصرع\nتبارك من لا يملك الملك غيره … متى تنقضي حاجات من ليس يشبع\nأي امرىء في غاية ليس نفسه … إلى غاية أخرى ، سواها ، تطلع"},{"id":"diwan-atahiya:77","bookId":"diwan-atahiya","type":"poem","seq":77,"chapter":"البحر: كامل تام","title":"أجل الفتى مما يؤمل أسرع","page":"","text":"أجل الفتى مما يؤمل أسرع … وأراه يجمع دائبا لا يشبع\nقل لي لمن اصبحت تجمع ما أرى … البعل عرسك لا أبا لك تجمع\nلا تنظرن إلى الهوى ، وانظر إلى … ريب الزمان بأهله ما يصنع\nالموت حق لا محالة دونه … ولكل موت علة لا تدفع\nالموت داء ليس يدفعه الدوا … ء إذا أتى ولكل جنب مصرع\nكم من أخي حيل دون لقائه ، … قلبي إليه ، من الجوانح ، منزع\nوإذا كبرت فهل لنفسك لذة … ما للكبير بلذة متمتع\nوإذا قنعت فأنت أغنى من غني … إن الفقير لكل من لا يقنع\nوإذا طلبت فلا إلى متضايق … من ضاق عنك فرزق ربك أوسع\nإن المطامع ما علمت مزلة … للطامعين ، وأين من لا يطمع\nإقنع ولا تنكر لربك قدرة ، … فالله يخفض من يشاء ، ويرفع\nولربما انتفع الفتى بضرار من … ينوي الضرار ، وضره من ينفع\nلا شيء أسرع من تقلب من له … أذن تسمعه الذي لا يسمع\nكل امريء متفرد بطباعه … ليس امروء إلا على ما يطبع"},{"id":"diwan-atahiya:78","bookId":"diwan-atahiya","type":"poem","seq":78,"chapter":"البحر: بسيط تام","title":"خذ من يقينك ما تجلو الظنون به ،","page":"","text":"خذ من يقينك ما تجلو الظنون به ، … وإن بدا لك أمر مشكل فدع\nقد يصبح المرء فيما ليس يدركه … مملق البال بين اليأس والطمع\nلم يعمل الناس في التصحيح بينهم ، … فاضطر بعضهم بعضا إلى الخدع"},{"id":"diwan-atahiya:79","bookId":"diwan-atahiya","type":"poem","seq":79,"chapter":"البحر: طويل","title":"لعمري لقد نوديت لو كنت تسمع ؛","page":"","text":"لعمري لقد نوديت لو كنت تسمع ؛ … ألم تر أن الموت ما ليس يدفع\nألم تر أن الناس في غفلاتهم … ألم تر أسباب الأمور تقطع\nألم تر لذات الجديد إلى البلى ؛ … ألم تر أسباب الحمام تشيع\nألم تر أن الفقر يعقبه الغنى … ألم تر أن الضيق قد يتوسع\nألم تر أن الموت يهتر شبيبة … وأن رماح الموت نحوك تشرع\nألم تر أن المرء يشبع بطنه … وناظره فيما ترى ليس يشبع\nأيا باني الدنيا لغيرك تبتني … ويا جامع الدنيا لغيرك تجمع\nألم تر أن المرء يحبس ماله … ووارثه فيه ، غدا ، يتمتع\nكأن الحماة المشفقين عليك قد … غدوا بك أو راحوا رواحا فأبرعوا\nوما هو إلا النعش لو قد دعوا به … تقل ، فتلقى فوقه ثم ترفع\nوما هو إلا حادث بعد حادث … فمن أي أنواع الحوادث تجزع\nألا ، وإذا أودعت توديع هالك ، … فآخر يوم منك يوم تودع\nألا وكما شيعت يوما جنازة ، … فأنت كما شيعتهم ستشيع\nرأيتك في الدنيا على ثقة بها ، … وإنك في الدنيا لأنت المروع\nولم تعن بالأمر الذي هو واقع … وكل امرىء يعنى بما يتوقع\nوإنك للمنقوض في كل حالة … وإن بني الدنيا على النقض يطبعوا\nإذا لم يضق قول عليك ، فقل به ، … وإن ضاق عنك القول فالصمت أوسع\nفلا تحتقر شيئا تصاغرت قدره ، … فإن حقيرا قد يضر وينفع\nتقلبت في الدنيا تقلب أهلها … وذو المال فيها حيث ما مال يتبع\nوما زلت أرمى كل يوم بعبرة … تكاد لها صم الجبال تصدع\nفما بال عيني لا تجود بمائها … وما بال قلبي لا يرق ويخشع\nتبارك من لا يملك الملك غيره … متى تنقضي حاجات من ليس يقنع\nوأي تمرىء في غاية ، ليس نفسه … إلى غاية أخرى ، سواها ، تطلع\nوبعض بني الدنيا لبعض ذريعة ، … وكل بكل قلما يتمتع\nيحب السعيد العدل عند احتجاجه … ويبغي الشقي البغي والبغي يصرع\nولم أر مثل الحق أقوى لحجة … يد الحق ، بين العلم والجهل ، تقرع\nوذو الفضل لا يهتز إن هزه الغنى … لفخر ولا إن عضه الدهر يفزع"},{"id":"diwan-atahiya:80","bookId":"diwan-atahiya","type":"poem","seq":80,"chapter":"البحر: منسرح","title":"ألحرص لؤم ، ومثله الطمع ،","page":"","text":"ألحرص لؤم ، ومثله الطمع ، … ما اجتمع الحرص قط والورع\nلو قنع الناس بالكفاف إذا … لا تسعوا في الذي به قنعوا\nللمرء فيما يقيمه سعة ، … لكنه ما يريد ما يسع\nيا حالب الدهر در أشطره ! … هل لك فيما حلبت منتفع ؟\nيا عجبا لامرىء تخادعه ال … الساعات عن نفسه فينخدع\nيا عجبا للزمان ، يأمنه … من قد يرى الصخر عنه ينصدع\nعجبت من آمن بمنزلة … يكثر فيها الأمراض والوجع\nعجبت من جهل قوم قد عرفوا … الحق فولوا عنه وما رجعوا\nالناس في زرع نسلهم ويد ال … الموت بها حصد كل ما زرعوا\nما شرف المرء كالقناعة والصب … ر ، على كل حادث يقع\nلم يزل القانعون أشرفنا … يا حبذا القانعون ما قنعوا\nللمرء في كل طرفة حدث … يذهب منه ما ليس يرتجع\nمن ضاق بالصبر عن مصيبته … ضاق ولم يتسع لها الجزع\nالشمس تنعاك حين تغرب لو … تدري وتنعاك حين تطلع\nحتى متى أنت لاعب أشر … حتى متى أنت بالصبا ولع\nإن الملوك الأولى مضوا سلفا … بادوا جميعا ، وما باد ما جمعوا\nيا ليت شعري عن الذين مضوا … قبلي إلى الترب ، ما الذي صنعوا\nبؤسا لهم أي منزل نزلوا … بؤسا لهم ، أي موقع وقعوا\nالحمد لله ! كل من سكن ال … الدنيا فعنها بالموت ينقطع"},{"id":"diwan-atahiya:81","bookId":"diwan-atahiya","type":"poem","seq":81,"chapter":"البحر: كامل تام","title":"إياك أعني يا ابن آدم فاستمع","page":"","text":"إياك أعني يا ابن آدم فاستمع … ودع الركون إلى الحياة فتنتفع\nلو كان عمرك ألف حول كامل … لم تذهب الأيام حتى تنقطع\nإن المنية لا تزال ملحة ، … حتى تشتت كل أمر مجتمع\nفاجعل لنفسك عدة للقاء من … لو قد أتاك رسوله لم تمتنع\nشغل الخلائق بالحياة ، وأغفلوا … زمنا ، حوادثه عليهم تقترع\nذهبت بنا الدنيا ، فكيف تغرنا ، … أم كيف تخدع من تشاء فينخدع\nوالمرء يوطنها ، ويعلم أنه … عنها إلى وطن سواها منقلع\nلم تقبل الدنيا على أحد بريتها … فمل من الحياة ولا شبع\nيا أيها المرء المضيع دينه ، … إحراز دينك خير شيء تصطنع\nنتها ، فمل من الحياة ولا شبع … فاعمل فما كلفت ما لا تستطع\nوالحق أفضل ما قصدت سبيله ، … والله أكرم من تزور وتنتجع\nفامهد لنفسك صالحا تجزى به ، … وانظر لنفسك أي أمر تتبع\nواجعل صديقك من وفى لصديقه ، … واجعل رفيقك ، حين تسقط ، من سرع\nوامنع فؤادك أن يميل بك الهوى … واشدد يديك بحبل دينك والورع\nواعلم بأن جميع ما قدمته … عند الإله ، موفر لك لم يضع\nطوبى لمن رزق القنوع ، ولم يرد … ما كان في يد غيره ، فيرى ضرع\nولئن طمعت لتصرعن ، فلا تكن … طمعا ، فإن الحر عبد ما طمع\nإنا لنلقى المرء تشره نفسه … فيضيق عنه كل أمر متسع\nوالمرء يمنع ما لديه ، ويبتغي … ما عند صاحبه ، ويغضب إن منع\nما ضر من جعل التراب فراشه … ألا ينام على الحرير ، إذا قنع"},{"id":"diwan-atahiya:82","bookId":"diwan-atahiya","type":"poem","seq":82,"chapter":"البحر: طويل","title":"هو الموت ، فاصنع كل ما أنت صانع ،","page":"","text":"هو الموت ، فاصنع كل ما أنت صانع ، … وأنت لكأس الموت لا بد جارع\nألا أيها المرء المخادع نفسه ! … رويدا أتدري من أراك تخادع\nويا جامع الدنيا لغير بلاغه … ستتركها فانظر لمن أنت جامع\nوكم قد رأينا الجامعين قد اصبحت … لهم ، بين أطباق التراب مضاجع\nلو أن ذوي الأبصار يرعون كلما … يرون ، لما جفت لعين مدامع\nفما يعرف العطشان من طال ريه ، … وما يعرف الشبعان من هو جائع\nوصارت بطون المرملات خميصة ، … وأيتامهم منهم طريد وجائع\nوإن بطون المكثرات كأنما … تنقنق في أجوافهن الضفادع\nوتصريف هذا الخلق لله وحده … وكل إليه ، لا محالة ، راجع\nولله في الدنيا أعاجيب جمة … تدل على تدبيره ، وبدائع\nولله في أسرار الأمور وإن جرت … بها ظاهرا ، بين العباد ، المنافع\nولله أحكام القضاء بعلمه … ألا فهو معط ما يشاء ومانع\nإذا ضن من ترجو عليك بنفعه ، … فذره ، فإن الرزق ، في الأرض ، واسع\nومن كانت الدنيا هواه وهمه ، … سبته المنى واستعبدته المطامع\nومن عقل استحيا ، وأكرم نفسه ، … ومن قنع استغنى فهل أنت قانع\nلكل امرىء رأيان رأي يكفه … عن الشيء ، أحيانا ، ورأي ينازع"},{"id":"diwan-atahiya:83","bookId":"diwan-atahiya","type":"poem","seq":83,"chapter":"البحر: رمل تام","title":"خير أيام الفتى يوم نفع","page":"","text":"خير أيام الفتى يوم نفع … واصطناع الخير أبقى ما صنع\nونظير المرء ، في معروفه ، … شافع بت إليه فشفع\nما ينال الخير بالشر ولا … يحصد الزارع إلا ما زرع\nليس كل الدهر يوما واحدا … ربما ضاق الفتى ثم اتسع\nخذ من الدنيا الذي درت به ، … واسل عما بان منها ، وانقطع\nإنما الدنيا متاع زائل ، … فاقتصد فيه وخذ منه ودع\nوارض للناس بما ترضى به ، … واتبع الحق فنعم المتبع\nوابغ ما اسطعت عن الناس الغنى ، … فمن احتاج إلى الناس ضرع\nاشهد الجامع لو أن قد أتى … يومه لم يغن عنه ما جمع\nإن للخير لرسما بيننا ، … طبع الله عليه ما طبع\nقد بلونا الناس في أخلاقهم … فرأيناهم لذي المال تبع\nوحبيب الناس من أطمعهم ، … إنما الناس جميعا بالطمع\nاحمد الله على تدبيره … قدر الرزق فعطى ومنع\nسمت نفسي ورعا تصدقه ، … فنهاها النقص عن ذاك الورع\nولنفسي حين تعطى فرح ، … واضطراب عند منع وجزع\nولنفسي غفلات لم تزل ، … ولها بالشيء ، أحيانا ، ولع\nعجبا من مطمئن آمن … إنما يغذى بألوان الفزع\nعجبا للناس ما أغفلهم … لوقوع الموت عما سيقع\nعجبا إنا لنلقى مرتعا … كلنا قد عاث فيه ورتع\nيا أخي الميت الذي شيعته … فحثي الترب عليه ورجع\nليت شعري ما تزودت من ال … زاد ، يا هذا ، لهول المطلع\nيوم يهدوك محبوك إلى … ظلمة القبر وضيق المضطجع"},{"id":"diwan-atahiya:84","bookId":"diwan-atahiya","type":"poem","seq":84,"chapter":"البحر: خفيف تام","title":"أيها المبصر ، الصحيح ، السميع ،","page":"","text":"أيها المبصر ، الصحيح ، السميع ، … أنت باللهو والهوى مخدوع\nكيف يعمى عن السبيل بصير … عجبا ذا ، أو يستصم سميع\nما لنا نستطيع أن نجمع الما … ل ، ورد الممات لا نستطيع\nحبب الأكل والشراب إلينا … وبناء القصور والتجميع\nوصنوف اللذات من كل لون ، … والفنا مقبل إلينا سريع\nليس ينجو من الفنا فاجر لبت … ولا السفلة الدني الوضيع\nكل حي سيطعم الموت كرها … ثم خلف الممات يوم فظيع\nكيف نلهو أو كيف نسلو من العي … هو منا مرجع منزوع\nنجمع الفاني والقليل من الما … ل وننسى الذي إليه الرجوع\nفي مقام ، تعشى العيون إليه ، … والملوك العظام فيه خضوع"},{"id":"diwan-atahiya:85","bookId":"diwan-atahiya","type":"poem","seq":85,"chapter":"البحر: رمل تام","title":"ربما ضاق الفتى ثم اتسع ،","page":"","text":"ربما ضاق الفتى ثم اتسع ، … وأخو الدنيا على النقص طبع\nإن من يطمع في كل منى … أطمعته النفس فيه لطمع\nللتقى عاقبة محمودة … والتقي المحض من كان يرع\nوقنوع المرء يحمي عرضه … ما القرير العين إلا من قنع"},{"id":"diwan-atahiya:86","bookId":"diwan-atahiya","type":"poem","seq":86,"chapter":"البحر: بسيط تام","title":"ما بال نفسك بالآمال منخدعه","page":"","text":"ما بال نفسك بالآمال منخدعه … وما لها لا ترعى بالوعظ منتفعه\nأما سمعت بمن أضحى له سبب ، … إلى النجاة ، بحرف واحد سمعه"},{"id":"diwan-atahiya:87","bookId":"diwan-atahiya","type":"poem","seq":87,"chapter":"البحر: خفيف تام","title":"أي عيش يكون أبلغ من عي","page":"","text":"أي عيش يكون أبلغ من عي … ش كفاف ، قوت ، بقدر البلاغ\nصاحب البغي ليس يسلم منه … وعلى نفسه بغى كل باغ\nرب ذي نعمة تعرض منها … حائل بينه ، وبين المساغ\nأبلغ الدهر في مواعظه بل … زاد فيهن لي على الإبلاغ\nغبنتني الأيام عقلي ، ومالي ، … وشبابي ، وصحتي ، وفراغي"},{"id":"diwan-atahiya:88","bookId":"diwan-atahiya","type":"poem","seq":88,"chapter":"البحر: كامل تام","title":"لله در أبيك أية ليلة","page":"","text":"لله در أبيك أية ليلة … مخضت صبيحتها بيوم الموقف\nلو أن عينا شاهدت ، من نفسها ، … يوم الحساب ، تمثلا لم تطرف"},{"id":"diwan-atahiya:89","bookId":"diwan-atahiya","type":"poem","seq":89,"chapter":"البحر: بسيط تام","title":"إن كان لا بد من موت فما كلفي","page":"","text":"إن كان لا بد من موت فما كلفي … وما عنائي بما يدعو إلى الكلف\nلا شيء للمرء أغنى من قناعته … ولا امتلاء لعين الملتهي الطرف\nمن فارق القصد لم يأمن عليه هوى … يدعو إلى البغي والعدوان والسرف\nما كل رأي الفتى يدعو إلى رشد … إذا بدا لك رأي مشكل فقف\nأخي ! ما سكنت ريح ولا عصفت ، … إلا لتؤذن بالنقصان والتلف\nما أقرب الحين ممن لم يزل بطرا … ولم تزل نفسه توفي على شرف\nكم من عزيز عظيم الشأن في جدث … مجدل ، بتراب الأرض ملتحف\nلله أهل قبور كنت أعهدهم … أهل القباب الرخاميات ، والغرف\nيا من تشرف بالدنيا وزينتها ، … حسب الفتى بتقى الرحمان من شرف\nوالخير والشر في التصوير بينهما … لو صورا لك ، بون غير مؤتلف\nأخي آخ المصفى ما استطعت ولا … تستعذبن مؤاخاة الأخ النطف\nما أحرز المرء من أطرافه طرفا ، … إلا تخونه النقصان من طرف\nوالله يكفيك إن أنت اعتصمت به ، … من يصرف الله عنه السوء ينصرف\nالحمد لله ، شكرا ، لا مثيل له ، … ما قيل شيء بمثل اللين واللطف"},{"id":"diwan-atahiya:90","bookId":"diwan-atahiya","type":"poem","seq":90,"chapter":"البحر: طويل","title":"متى تتقضى حاجة المتكلف ، متى تتقضى حاجة المتكلف ،","page":"","text":"متى تتقضى حاجة المتكلف ، متى تتقضى حاجة المتكلف ، … ولا سيما من مترف النفس مسرف\nطلبت الغنى في كل وجه فلم أجد … سبيل الغنى ، إلا سبيل التعفف\nإذا كنت لا ترضى بشيء تناله … وكنت على ما فات حم التلهف\nفلست من الهم العريض بخارج ، … ولست من الغيظ الطويل بمشتف\nأراني بنفسي معجبا متعززا … كأني على الآفات لست بمشرف\nوإني لعين البائس الواهن القوى ، … وعين الضعيف البائس المتطرف\nوليس امرو لم يرع منك بجهده … جميع الذي ترعاه منه ، بمنصف\nخليلي ما أكفى اليسير من الذي … نحاول ، إن كنا بما عف نكتفي\nوما أكرم العبد الحريص على الندى ، … وأشرف نفس الصابر المتعفف"},{"id":"diwan-atahiya:91","bookId":"diwan-atahiya","type":"poem","seq":91,"chapter":"البحر: بسيط تام","title":"الله كاف فما لي دونه كاف","page":"","text":"الله كاف فما لي دونه كاف … على اعتدائي على نفسي وإسرافي\nتشرف الناس بالدنيا وقد غرقوا … فيها فكل على أمواجها طاف\nهم العبيد لدار قلب صاحبها ، … ما عاش ، منها على خوف وإيجاف\nحسب الفتى بتقى الرحمان من شرف … وما عبيدك ، يا دنيا ، بأشراف\nيا دار ! كم قد رأينا فيك من أثر ، … ينعى الملوك إلينا ، دارس ، عاف\nأودى الزمان بأسلافي ، وخلفني ، … وسوف يلحقني يوما بأسلافي\nكأننا قد توافينا بأجمعنا … في بطن ظهر عليه مدرج السافي\nأخي ! عندي من الأيام تجربة ، … فيما أظن وعلم بارع شاف\nلا تمش في الناس إلا رحمة لهم … ولا تعاملهم إلا بإنصاف\nواقطع قوى كل حقد أنت مضمره … إن زال ذو زلة ، أو إن هفا هاف\nوارغب بنفسك عما لا صلاح له ، … وأوسع الناس من بر ، وإلطاف\nوإن يكن أحد أولاك صالحة … فكافه فوق ما أولى بأضعاف\nولا تكشف مسيئا عن إساءته … وصل حبال أخيك القاطع ، الجافي\nفتستحق من الدنيا سلامتها … وتستقل بعرض وافر ، واف\nما أحسن الشغل في تدبير منفعة ، … أهل الفراغ ذوو خوض وإرجاف"},{"id":"diwan-atahiya:92","bookId":"diwan-atahiya","type":"poem","seq":92,"chapter":"البحر: مجزوء الوافر","title":"ألا أين الألى سلفوا ،","page":"","text":"ألا أين الألى سلفوا ، … دعوا للموت واختطفوا\nفوافوا حين لا تحف ، … ولا طرف ولا لطف\nترص عليهم حفر … وتبنى ثم تنخسف\nلهم من تربها فرش … ومن رضراضها لحف\nتقطع منهم سبب ال … الرجاء فضيعوا وجفوا\nتمر بعسكر الموتى ، … وقلبك منه لا يجف\nكأن مشيعيك ، وقد … رموابك ، ثم ، وانصرفوا\nفنون رداك ، يا دنيا ، … لعمري فوق ما أصف\nفأنت الدار فيك الظلم … م ، والعدوان ، والسرف\nوأنت الدار فيك الهم … والأحزان والأسف\nوأنت الدار فيك الغد … ر ، والتنغيص ، والكلف\nوفيك الحبل مضطرب ؛ … وفيك البال منكسف\nوفيك لساكنيك الغبن … والآفات والتلف\nوملكك فيهه دول ، … بها الأقدار تختلف\nكأنك بينهم كرة … ترامى ثم تلتقف\nترى الأيام لا ينظر … ن والساعات لا تقف\nولن يبقى لأهل الأر … ض لا عز ، ولا شرف\nوكل دائم الغفلا … ت والأنفاس تختطف\nوأي الناس إلا مو … قن بالموت معترف\nوخلق الله مشتبه ، … وسعي الناس مختلف\nوما الدنيا بباقية … ستنزح ثم تنتسف\nوقول الله ذاك لنا … وليس لقوله خلف"},{"id":"diwan-atahiya:93","bookId":"diwan-atahiya","type":"poem","seq":93,"chapter":"البحر: طويل","title":"أتبكي لهذا الموت أم أنت عارف","page":"","text":"أتبكي لهذا الموت أم أنت عارف … بمنزلة تبقى وفيها المتالف\nكأنك قد غيبت في اللحد والثرى ، … فتلقى كما لاقى القرون السوالف\nأرى الموت قد أفنى القرون التي مضت … فلم يبق ذو إلف ولم يبق آلف\nكأن الفتى لم يفن في الناس ساعة … إذا أعصبت يوما عليه اللفائف\nوقامت عليه عصبة يندبونه ، … فمستعبر يبكي وآخر هاتف\nوغودر في لحد ، كريه حلوله ، … وتعقد من لبن عليه السقائف\nيقل الغنا عن صاحب اللحد والثرى … بما ذرفت فيه العيون الذوارف\nوما من يخاف البعث والنار آمن ، … ولكن حزين موجع القلب خائف\nإذا عن ذكر الموت أوجع قلبه … وهيج ، أحزانا ، ذنوب سوالف\nوأعلم غير الظن أن ليس بالغا … أعاجيب ما يلقى من الناس ، واصف"},{"id":"diwan-atahiya:94","bookId":"diwan-atahiya","type":"poem","seq":94,"chapter":"البحر: سريع","title":"تزيده الأيام إن أقبلت","page":"","text":"تزيده الأيام إن أقبلت … شدة خوف لتصاريفها\nكأنها في حال إسعافها … تسمعه أوقات تخويفها"},{"id":"diwan-atahiya:95","bookId":"diwan-atahiya","type":"poem","seq":95,"chapter":"البحر: طويل","title":"ألم تر هذا الموت يستعرض الخلقا","page":"","text":"ألم تر هذا الموت يستعرض الخلقا … ترى أحدا يبقى فتطمع أن تبقى\nلكل امرىء حي من الموت خطة … يصير إليا حين يستكمل الرزقا\nتزود من الدنيا ، فإنك شاخص … إلى المنتهى واجعل مطيتك الصدقا\nفأمسك من الدنيا الكفاف ، وجد على … أخيك ، وخذ بالرفق ، واجتنب الخرقا\nفإني رأيت المرء يحرم حظه … من الدين والدنيا ، إذا حرم الرفقا\nولا تجعلن الحمد إلا لأهله ، … ولا تدع الإمساك بالعروة الوثقى\nولا خير فيمن لا يؤاسي بفضله … ولا خير فيمن لا يرى وجهه طلقا\nوليس الفتى في فضله بمقصر … إذا ما اتقى الرحمان ، واتبع الحقا"},{"id":"diwan-atahiya:96","bookId":"diwan-atahiya","type":"poem","seq":96,"chapter":"البحر: منسرح","title":"ما أغفل الناس والخطوب بهم","page":"","text":"ما أغفل الناس والخطوب بهم … في خبب مرة ، وفي عنق\nوفي فناء الملوك معتبر … كفى به حجة على السوق"},{"id":"diwan-atahiya:97","bookId":"diwan-atahiya","type":"poem","seq":97,"chapter":"البحر: طويل","title":"طلبت أخا في الله في الغرب والشرق","page":"","text":"طلبت أخا في الله في الغرب والشرق … فأعوزني هذا ، على كثرة الخلق\nفصرت وحيدا بينهم ، متصبرا ، … على الغدر منهم ، والملالة والمذق\nأرى من بها يقضي علي لنفسه … ولم أر من يرعى علي ولا يبقي\nوكم من أخ قد ذقته ذا بشاشة … إذا ساغ في عيني يغص به حلقي\nولم أر كالدنيا ، وكشفي لأهلها ، … فما انكشفوا لي عن وفاء ولا صدق\nولم أر أمرا واحدا من أمورها … أعز ، ولا أعلى من الصبر للحق"},{"id":"diwan-atahiya:98","bookId":"diwan-atahiya","type":"poem","seq":98,"chapter":"البحر: خفيف تام","title":"قطع الموت كل عقد وثيق ،","page":"","text":"قطع الموت كل عقد وثيق ، … ليس للميت بعده من صديق\nمن يمت يعدم النصيحة والإش … فاق من كل ناصح ، وشفيق\nنزل الساكن الثرى من ذوي … طاف في المنزل البعيد السحيق\nكل أهل الدنيا تعوم على الغف … منها في غمر بحر عميق\nيتبارون في السباح فهم من … بين ناج منهم ، وبين غريق\nوالتماسي لما أطالب منها … لم أكن ، لالتماسه ، بحقيق"},{"id":"diwan-atahiya:99","bookId":"diwan-atahiya","type":"poem","seq":99,"chapter":"البحر: مديد تام","title":"عامل الناس برأي رفيق","page":"","text":"عامل الناس برأي رفيق … والق من تلقى بوجه طليق\nفإذا أنت جميل الثناء … وإذا أنت كثير الصديق"},{"id":"diwan-atahiya:100","bookId":"diwan-atahiya","type":"poem","seq":100,"chapter":"البحر: رمل تام","title":"داو بالرفق جراحات الخرق","page":"","text":"داو بالرفق جراحات الخرق … وابل قبل الذم قبل الذم والحمد وذق\nوسع الناس بخلق حسن ، … لم يضق شيء على حسن الخلق\nكل من لم تتسع أخلاقه ، … بعد إحسان إليه ينسحق\nكم ترانا يا أخي نبقى على … جولان الموت في هذا الأفق\nنحن أرسال إلى دار البلى … نتوالى عنقا ، بعد عنق"},{"id":"diwan-atahiya:101","bookId":"diwan-atahiya","type":"poem","seq":101,"chapter":"البحر: بسيط تام","title":"الرفق يبلغ ما لا يبلغ الخرق ،","page":"","text":"الرفق يبلغ ما لا يبلغ الخرق ، … وقل في الناس من يصفو له خلق\nلم يفلق المرء عن رشد فيتركه … إلا دعاه إلى ما يكره الفلق\nالباطل ، الدهر ، يلفى لا ضياء له ، … والحق أبلج فيه النور يأتلق\nمتى يفيق حريص دائب أبدا ، … والحرص داء له تحت الحشا قلق\nيستغنم الناس من قوم فوائدهم … وإنما هي في أعناقهم ربق\nفيجهد الناس ، في الدنيا ، منافسة ، … وليس للناس شيء غير ما رزقوا\nيا من بنى القصر في الدنيا ، وشيده ، … أسست قصرك حيث السيل والغرق\nلا تغفلن ، فإن الدار فانية ، … وشربها غصص أو صفوها رنق\nوالموت حوض كريه أنت وارده … فانظر لنفسك قبل الموت يا مذق\nاسم العزيز ذليل عند ميتته ؛ … واسم الجديد ، بعيد الجدة ، الخلق\nيبلى الشباب ، ويفني الشيب نضرته ، … كما تساقط ، عن عيدانها ، الورق\nما لي أراك ، وما تنفك من طمع ، … يمتد منك إليه الطرف ، والعنق\nتذم دنياك ذما لا تبوح به ، … إلا وأنت لها في ذاك معتنق\nفلو عقلت لأعددت الجهاز لها ، … بعد الرحيل بها ما دام لي رمق\nإذا نظرت من الدنيا إلى صور ، … تخيلت لك يوما فوقها الخرق\nما نحن إلا كركب ضمه سفر … يوما ، إلى ظل في ثمت افترقوا\nولا يقيم على الأسلاف غابرهم ، … كأنهم بهم من بعدهم لحقوا\nما هب أو دب يفنى لا بقاء له … والبر ، و\nنستوطن الأرض دارا للغرور بها … وكلنا راحل عنها ، ومنطلق\nلقد رأيت ، وما عيني براقدة ، … قتلى الحوادث بين الخلق تخترق\nكم من عزيز أذل الموت مصرعه … كانت ، على رأسه ، الرايات تختفق\nكل امرء وله رزق سيبلغه … والله يرزق لا كيس ولا حمق\nإذا نظرت إلى دنياك مقبلة ، … فلا يغرنك تعظيم ولا ملق\nأخي إنا لنحن الفائزون غدا … إن سلم الله من دار لها علق\nفالحمد لله حمدا لا انقطاع له ، … ما إن يعظم إلا من له ورق\nوالحمد لله حمدا دائما أبدا … فاز الذين ، إلى ما عنده ، سبقوا\nما أغفل الناس عن يوم انبعاثهم … ويوم يلجمهم ، في الموقف ، العرق"},{"id":"diwan-atahiya:102","bookId":"diwan-atahiya","type":"poem","seq":102,"chapter":"البحر: طويل","title":"ألا إنما الإخوان عند الحقائق ،","page":"","text":"ألا إنما الإخوان عند الحقائق ، … ولا خير في ود الصديق المماذق\nلعمرك ما شيء من العيش كله ، … أقر لعيني من صديق موافق\nوكل صديق ليس في الله وده … فإني به ، في وده ، غير واثق\nأحب أخا في الله ما صح دينه ، … وأفرشه ما يشتهي من خلائق\nوأرغب عما فيه ذل دنية ، … وأعلم أن الله ، ما عشت ، رازقي\nصفي ، من الإخوان ، كل موافق … صبور على ما نابه من بوائق"},{"id":"diwan-atahiya:103","bookId":"diwan-atahiya","type":"poem","seq":103,"chapter":"البحر: مجزوء الكامل","title":"انظر لنفسك يا شقي","page":"","text":"انظر لنفسك يا شقي … حتى متى لا تتقي\nأو ما ترى الأيام … تلس النفوس ، وتنتقي\nانظر بطرفك هل ترى … في مغرب ، أو مشرق\nأحدا وفى لك في الشدائد … إن لجأت بموثق\nكم من أخ غمضته … بيدي نصيح مشفق\nويئست منه فلست أط … أن يعيش فنلتقي\nلا تكذبن ، فإنه … من يجتمع يتفرق\nوالموت غاية من مضى … منا وموعد من بقي"},{"id":"diwan-atahiya:104","bookId":"diwan-atahiya","type":"poem","seq":104,"chapter":"البحر: طويل","title":"وما الموت إلا رحلة ، غير أنها","page":"","text":"وما الموت إلا رحلة ، غير أنها … من المنزل الفاني إلى المنزل الباقي"},{"id":"diwan-atahiya:105","bookId":"diwan-atahiya","type":"poem","seq":105,"chapter":"البحر: طويل","title":"أرى الشيء أحيانا بقلبي معلقا","page":"","text":"أرى الشيء أحيانا بقلبي معلقا … فلا بد أن يبلى وأن يتمزقا\nتصرفت أطوارا أرى كل عبرة … وكان الصبا مني جديدا ، فأخلقا\nوكل امرئ في سعيه الدهر ربما … يفتح أحيانا له أو يغلقا\nوما اجتمع الإلفان إلا تفرقا … وحسب امرىء من رأيه أن يوفقا"},{"id":"diwan-atahiya:106","bookId":"diwan-atahiya","type":"poem","seq":106,"chapter":"البحر: طويل","title":"نموت جميعا كلنا ، غير ما شك ،","page":"","text":"نموت جميعا كلنا ، غير ما شك ، … ولا أحد يبقى سوى مالك الملك\nأيا نفس أنت الدهر في حال غفلة … وليست صروف الدهر غافلة عنك\nأيا نفس كم لي عنك من يوم صرعة … إلى الله أشكو ما أعالجه منك\nأيا نفس إن لم أبك مما أخافه … عليك غدا عند الحساب فمن يبكي\nأيا نفس هذي الدار لا دار قلعة … فلا تجعلن القصد في منزل الإفك\nأيا نفس لا تنسي عن الله فضله … فتأييده ملكي ، وجذلانه هلكي\nوليس دبيب الذر فوق الصفاة ، في … الظلام بأخفى من رياء ولا شرك"},{"id":"diwan-atahiya:107","bookId":"diwan-atahiya","type":"poem","seq":107,"chapter":"البحر: كامل تام","title":"إن كنت تبصر ما عليك ومالكا","page":"","text":"إن كنت تبصر ما عليك ومالكا … فانظر لمن تمضي وتترك مالكا\nولقد ترى أن الحوادث جمة ، … وترى المنية حيث كنت حيالكا\nيا إبن آدم كيف ترجو أن يكو … الرأي رأيك والفعال فعالكا"},{"id":"diwan-atahiya:108","bookId":"diwan-atahiya","type":"poem","seq":108,"chapter":"البحر: طويل","title":"كأن المنايا قد قصدن إليكا ،","page":"","text":"كأن المنايا قد قصدن إليكا ، … يردنك فانظر ما لهن لديكا\nسيأتيك يوم لست فيه بمكرم … بأكثر من حثو التراب عليكا"},{"id":"diwan-atahiya:109","bookId":"diwan-atahiya","type":"poem","seq":109,"chapter":"البحر: وافر تام","title":"خذ الدنيا بأيسرها عليكا","page":"","text":"خذ الدنيا بأيسرها عليكا … ومل عنها إذا قصدت إليكا\nفإن جميع ما خولت منها … ستنفضه جميعا من يديكا"},{"id":"diwan-atahiya:110","bookId":"diwan-atahiya","type":"poem","seq":110,"chapter":"البحر: منسرح","title":"المرء مستأسر بما ملكا ،","page":"","text":"المرء مستأسر بما ملكا ، … ومن تعامى عن قدره هلكا\nمن لم يصب من دنياه آخرة ، … فليس منها بمدرك دركا\nللمرء ما قدمت يداه من ال … الفضل وللوارثين ما تركا\nيا سكرة الموت أنت واقعة … للمرء في أي ا فة سلكا\nيا سكرة الموت قد نصبت لهذا … الخلق في كل مسلك شركا\nأخي إن الخطوب مرصدة … بالموت لا بد منه لي ولكا\nما عذر من لم تنم تجاربه … وحنكته الأمور ، فاحتنكا\nخضت المنى ثم صرت بعد إلى … مولاك في وحلهن مرتبكا\nما أعجب الموت ثم أعجب منه … ه مؤمن ، موقن به ضحكا\nحن لأهل القبور من ثقتي … إن حن قلبي إليهم وبكى\nالحمد لله حيثما زرع ال … الخير امرء طاب زرعه وزكا\nلا تجتني الطيبات يوما من … غرس يد كان غرسها الحسكا\nإن المنايا لا تخطئن ولا … تبقين لا سوقة ولا ملكا\nالحمد للخالق الذي حرك ال … الساكن منا وسكن الحركا\nوقامت الأرض والسماء به ، … وما دحى منهما وما سمكا\nوقلب الليل والنهار وصب … رزق صبا ، ودبر الفلكا"},{"id":"diwan-atahiya:111","bookId":"diwan-atahiya","type":"poem","seq":111,"chapter":"البحر: مجزوء الوافر","title":"رأيت الفضل متكئا","page":"","text":"رأيت الفضل متكئا … يناجي\nفأرسل عينه لما … رآني مقبلا وبكى\nفلما أن حلفت له … بأني صائم ضحكا"},{"id":"diwan-atahiya:112","bookId":"diwan-atahiya","type":"poem","seq":112,"chapter":"البحر: منسرح","title":"لا رب أرجوه لي سواكا ،","page":"","text":"لا رب أرجوه لي سواكا ، … إذ لم يخب سعي من رجاكا\nأنت الذي لم تزل خفيا … لم يبلغ الوهم منتهاكا\nإن أنت لم تهدنا ضللنا … يا رب إن الهدى هداكا\nأحطت علما بنا جميعا ، … أنت ترانا ولا نراكا"},{"id":"diwan-atahiya:113","bookId":"diwan-atahiya","type":"poem","seq":113,"chapter":"البحر: هزج","title":"رأيت الشيب يعروكا","page":"","text":"رأيت الشيب يعروكا … بأن الموت ينحوكا\nفخذ حذرك ، يا هذا ، … فإني لست آلوكا\nولا تزدد من الدنيا ، … فتزدادن بها نوكا\nفتقوى الله تغنيك … وإن سميت صعلوكا\nتناومت عن الموت … وداع الموت يدعوك\nوحاديه ، وإن نمت ، … حثيث السير يحدوكا\nفلا يومك ينساك ، … ولا رزقك يعدوكا\nمتى ترغب إلى الناس ، … تكن في الناس مملوكا\nإذا ما أنت خففت … عن الناس أحبوكا\nوثقلت ملوك … وعابوك ، وسبوكا\nإذا ما شئت أن تعصى … فمر من ليس يرجوكا\nومر من ليس يخشاك … فيدمى عندها فوكا"},{"id":"diwan-atahiya:114","bookId":"diwan-atahiya","type":"poem","seq":114,"chapter":"البحر: منسرح","title":"لا تنس ، واذكر سبيل من هلكا ،","page":"","text":"لا تنس ، واذكر سبيل من هلكا ، … ستسلك المسلك الذي سلكا"},{"id":"diwan-atahiya:115","bookId":"diwan-atahiya","type":"poem","seq":115,"chapter":"البحر: بسيط تام","title":"طول التعاشر بين الناس مملول","page":"","text":"طول التعاشر بين الناس مملول … ما لابن آدم إن فتشت معقول\nللمرء ألوان دنيا : رغبة وهوى ، … وعقله أبدا ما عاش مدخول\nيا راعي النفس لا تغفل رعايتها ، … فأنت عن كل ما استرعيت مسؤول\nخذ ما عرفت ودع ما أنت جاهله … للأمر وجهان : معروف ، ومجهول\nواحذر ، فلست من الأيام منفلتا ، … حتى يغولك من أيامك الغول\nوالدائرات بريب الدهر دائرة … والمرء عن نفسه ما عاش مختول\nلن تستتم جميلا أنت فاعله … إلا وأنت طليق الوجه ، بهلول\nما أوسع الخير فابسط راحتيك به ، … وكن كأنك ، عند الشر ، مغلول\nالحمد لله في آجالنا قصر ، … نبغي البقاء وفي آمالنا طول\nنعوذ بالله من خذلانه أبدا … فإنما الناس معصوم ومخذول\nإني لفي منزل ما زلت أعمره ، … على يقيني بأني عنه منقول\nوأن رحلي ، وإن أوثقته ، لعلى … مطية ، من مطايا الحين ، محمول\nولو تأهبت والأنفاس في مهل … والخير بيني وبين العيش مقبول\nوادي الحياة محل لا مقام به ، … لنازليه ، ووادي الموت محلول\nوالدار دار أباطيل مشبهة … الجد مر بها ، والهزل معسول\nوليس من موضع يأتيه ذو نفس ، … إلا وللموت سيف فيه مسلول\nلم يشغل الموت عنا مذ أعد لنا … وكلنا عنه باللذات مشغول\nومن يمت فهو مقطوع ومجتنب … والحي ما عاش مغشي ، وموصول\nكل ما بدا لك فالآكال فانية … وكل ذي أكل لا بد مأكول\nوكل شيء من الدنيا فمنتقض … وكل عيش من الدنيا ، فمملول\nسبحان من أرضه للخلق مائدة ، … كل يوافيه رزق منه مكفول\nغدى الأنام وعشاهم ، فأوسعهم ، … وفضله لبغاة الخير مبذول\nيا طالب الخير ابشر واستعد له … فالخير أجمع عند الله مأمول"},{"id":"diwan-atahiya:116","bookId":"diwan-atahiya","type":"poem","seq":116,"chapter":"البحر: كامل تام","title":"قطعت منك حبائل الآمال ،","page":"","text":"قطعت منك حبائل الآمال ، … وحططت عن ظهر المطي رحالي\nويئست أن أبقى لشيء نلت مما … فيك يا دنيا وإن يبقى لي\nفوجدت برد اليأس بين جوانحي ، … وأرحت من حلي ومن ترحالي\nولئن يئست لرب برقة خلب … برقت لذي طمع ، وبرقة آل\nفالآن ، يا دنيا ، عرفتك فاذهبي ، … يا دار كل تشتت وزوال\nوالآن صار لي الزمان مؤدبا … فغدا علي وراح بالأمثال\nوالآن أبصرت السبيل إلى الهدى … وتفرغت هممي عن الأشغال\nولقد أقام لي المشيب نعاته ، … تفضي إلي بمفرق وقذال\nولقد رأيت الموت يبرق سيفه … بيد المنية ، حيث كنت ، حيالي\nولقد رأيت عرى الحياة تخرمت ، … ولقد تصدى الوارثون لمالي\nولقد رأيت على الفناء أدلة ، … فيما تنكر من تصرف حالي\nوإذا اعتبرت رأيت خطب حوادث … يجرين بالأرزاق ، والآجال\nوإذا تناسبت الرجال ، فما أرى … نسبا يقاس بصالح الأعمال\nوإذا بحثت عن التقي وجدته … رجلا ، يصدق قوله بفعال\nوإذا اتقى الله امرؤ ، وأطاعه ، … فيداه بين مكارم ومعال\nوعلى التقي إذا ترسخ في التقى … تاجان تاج سكينة وجلال\nوالليل يذهب والنهار ، تعاورا … بالخلق في الإدبار والإقبال\nوبحسب من تنعى إليه نفسه … منه بأيام خلت وليال\nإضرب بطرفك حيث شئت ، فأنت في … عبر لهن تدارك وتوال\nيبكي الجديد وأنت في تجديده … وجميع ما جددت منه ، فبال\nيا أيها البطر الذي هو في غد ، … في قبره ، متفرق الأوصال\nولقل ما تلقى أغر لنفسه … من لاعب مرح بها ، مختال\nيا تاجر الغي المضر برشده ، … حتى متى بالغي أنت تغالي\nالحمد لله الحميد بمنه … خسرت ولم تربح يد البطال\nلله يوم تقشعر جلودهم ، … وتشيب منه ذوائب الأطفال\nيوم النوازل والزلازل ، والحوا … مل فيه إذ يقذفن بالأحمال\nيوم التغابن والتباين والتنا … زل والأمور عظيمة الأهوال\nيوم ينادى فيه كل مضلل … بمقطعات النار وألأغلال\nللمتقين هناك نزل كرامة … علت الوجوه بنضرة ، وجمال\nزمر اضاءت للحساب وجوهها … فلها بريق عندها وتلالي\nوسوابق غر محجلة جرت … خمص البطون خفيفة الأثقال\nمن كل أشعث كان أغبر ناحلا ، … خلق الرداء مرقع السربال\nحيل ابن آدم في الأمور كثيرة ، … \nنزلو بأكرم سيد فأظلهم … في دار ملك جلالة ، وظلال\nومن النعاة إلى ابن آدم نفسه ، … حرك الخطى ، وطلوع كل هلال\nما لي أراك لحر وجهك مخلقا ، … أخلقت ، يا دنيا ، وجوه رجال\nكن بالسؤال أشد عقد ضنانة ، … ممن يضن عليك بالأموال\nوصن المحامد ما استطعت فإنها … في الوزن ترجح بذل كل نوال\nولقد عجبت من المثمر ماله ، … نسي المثمر زينة الإقلال\nوإذا امرؤ لبس الشكوك بعزمه … سلك الطريق على عقود ضلال\nوإذا ادعت خدع الحوادث قسوة ، … شهدت لهن مصارع الأبطال"},{"id":"diwan-atahiya:117","bookId":"diwan-atahiya","type":"poem","seq":117,"chapter":"البحر: سريع","title":"يا ذا الذي يقرأ في كتبه","page":"","text":"يا ذا الذي يقرأ في كتبه … ما أمر الله ، ولا يعمل\nقد بين الرحمان مقت الذي … يأمر بالحق ولا يفعل\nمن كان لا تشبه أفعاله … أقواله ، فصمته أجمل\nمن عذل الناس فنفسي بما … قد فارقت من دينها أعذل\nإن الذي ينهى ، ويأتي الذي … عنه نهى في الخلق ، لا يعدل\nوالراكب الذنب على جهله … اعذر ممن كان لا يجهل\nلا تخلطن ما يقبل الله من … فعل بقول منك لا يقبل"},{"id":"diwan-atahiya:118","bookId":"diwan-atahiya","type":"poem","seq":118,"chapter":"البحر: بسيط تام","title":"ما للجديدين لا يبلى اختلافهما ،","page":"","text":"ما للجديدين لا يبلى اختلافهما ، … وكل غض جديد فيهما بال\nيا من سلا عن حبيب بعد ميتته ، … كم بعد موتك أيضا عنك من سال\nكأن كل نعيم أنت ذائقه ، … من لذة العيش ، يحكي لمعة الآل\nلا تلعبن بك الدنيا ، وأنت ترى … ما شئت من غير فيها وأمثال\nما حلة الموت إلا كل صالحة … أو لا فما حيلة فيه لمحتال"},{"id":"diwan-atahiya:119","bookId":"diwan-atahiya","type":"poem","seq":119,"chapter":"البحر: خفيف تام","title":"كل حي كتابه معلوم","page":"","text":"كل حي كتابه معلوم … لا شقاء ، ولا نعيم يدوم\nيحسد المرء في النعيم صباحا ، … ثم يمسي وعيشه مذموم\nوإذا ما الفقير قنعه الل … ه ، فسيان بؤسه والنعيم\nمن أراد الغنى فلا يسأل النا … س ، فإن السؤال ذل ولوم\nإن في الصبر والقنوع غنى الده … ر ، حرص الحريص فقر مقيم\nإنما الناس كالبهائم في الرز … ق ، سواء جهولهم والعليم\nليس حزم الفتى يجر له الرز … ق ولا عاجزا يعد العديم"},{"id":"diwan-atahiya:120","bookId":"diwan-atahiya","type":"poem","seq":120,"chapter":"البحر: بسيط تام","title":"هو التنقل من يوم إلى يوم","page":"","text":"هو التنقل من يوم إلى يوم … كأنه ما تريك العين في النوم\nإن المنايا وإن أصبحت في لعب … تحوم حولك حوما أيما حوم\nوالدهر ذو دول ، فيه لنا عجب ، … دنيا تنقل من قوم إلى قوم"},{"id":"diwan-atahiya:121","bookId":"diwan-atahiya","type":"poem","seq":121,"chapter":"البحر: سريع","title":"ماذا يفوز الصالحون به","page":"","text":"ماذا يفوز الصالحون به … سقيت قبور الصالحين ديم\nلولا بقايا الصالحين عفا … ما كان أثبته لنا ، ورسم\nسبحان من سبقت مشيته ، … وقضى بذاك لنفسه وحكم"},{"id":"diwan-atahiya:122","bookId":"diwan-atahiya","type":"poem","seq":122,"chapter":"البحر: كامل تام","title":"أهل القبور عليكم مني السلام ،","page":"","text":"أهل القبور عليكم مني السلام ، … إني أكلمكم وليس بكم كلام\nلا تحسبوا أن الأحبة لم يسغ … من بعدكم ، لهم الشراب ولا الطعام\nكلا لقد رفضوكم ، واستبدلوا … بكم ، وفرق ذات بينكم الحمام\nوالخلق كلهم كذاك وكل من … قد مات ليس له على حي ذمام\nساءلت أجداث الملوك ، فأخبرت … ي أنهم ، فيهن أعضاء وهام\nلله ما وارى التراب من الألى … كانوا الكرام هم ، إذا ذكر الكرام\nلله ما وارى التراب من الألى … كانوا وجارهم منيع لا يضام\nيا صاحبي ! نسيت دار إقامتي ، … وعمرت دارا ليس لي فيها مقام\nدار يريد الدهر نقلة أهلها ، … وكأنهم عما يراد بهم نيام\nما نلت منها لذة إلا وقد … أبت الحوادث أن يكون لها تمام"},{"id":"diwan-atahiya:123","bookId":"diwan-atahiya","type":"poem","seq":123,"chapter":"قصائد","title":"يا عين ! قد نمت ، فإستنبهي ،","page":"","text":"يا عين ! قد نمت ، فإستنبهي ، … ما اجتمع الخوف وطيب المنام\nأكره أن ألقى حمامي ، ولا … بد لحي من لقاء الحمام\nلا بد من موت بدار البلى … والله بعد الموت يحيي العظام\nيا طالب الدنيا ولذاتها … هل لك في ملك طويل المقام ؟\nمن جاور الرحمن ، في داره ، … تمت له النعمة كل التمام"},{"id":"diwan-atahiya:124","bookId":"diwan-atahiya","type":"poem","seq":124,"chapter":"البحر: خفيف تام","title":"لعظيم من الأمور خلقنا","page":"","text":"لعظيم من الأمور خلقنا … غير أنا مع الشقاء ننام\nكل يوم يحيط آجالنا الده … ر ، ويدنو ، إلى النفوس ، الحمام\nلا نبالي ولا نراه غراما … ذا لعمري ، لو اتعظنا الغرام\nمن رجونا لديه دنيا وصلنا … ه ، وقلنا له : عليك السلام\nما نبالي أمن حرام جمعنا ، … أم حلال ولا يحل الحرام\nهمنا اللهو ، والتكاثر في الما … ل ، وهذا البناء والخدام\nكيف نبتاع فاني العيش بالدا … ئم أين العقول والأحلام\nلو جهلنا فناءه وقع العذ … ر ، ولكن كلنا علام"},{"id":"diwan-atahiya:125","bookId":"diwan-atahiya","type":"poem","seq":125,"chapter":"البحر: كامل تام","title":"سميت نفسك ، بالكلام ، حكيما ،","page":"","text":"سميت نفسك ، بالكلام ، حكيما ، … ولقد أراك على القبيح مقيما\nولقد أراك من الغواية مثريا … ولقد أراك من الرشاد عديما\nأغفلت ، من دار البقاء ، نعيمها ، … وطلبت ، في دار الفناء ، نعيما\nمنع الجديدان البقاء ، وأبليا … أمما خلون من القرون قديما\nوعصيت ربك يا ابن آدم جاهدا ، … فوجدت ربك ، إذ عصيت ، حليما\nوسألت ربك يا ابن آدم رغبة … فوجدت ربك ، إذ سألت كريما\nودعوت ربك يا ابن آدم رهبة ، … فوجدت ربك ، إذ دعوت ، رحيما\nفلئن شكرت لتشكرن لمنعم ، … ولئن كفرت لتكفرن عظيما\nفتبارك الله الذي هو لم يزل … ملكا ، بما تخفي الصدور ، عليما"},{"id":"diwan-atahiya:126","bookId":"diwan-atahiya","type":"poem","seq":126,"chapter":"البحر: بسيط تام","title":"يا نفس ! ما هو إلا صبر أيام ،","page":"","text":"يا نفس ! ما هو إلا صبر أيام ، … كأن لذاتها أضغاث أحلام\nيا نفس ! ما لي لا أنفك من طمع … طرفي غليه سريع طامح سام\nيا نفس ! كوني ، عن الدنيا ، مبعدة ، … وخلفيها ، فإن الخير قدامي\nيا نفس ! ما الذخر إلا ما انتفعت به … بالقبر ، يوم يكون الدفن إكرامي\nوللزمان وعيد في تصرفه ، … إن الزمان لذو نقض وإبرام\nأما المشيب فقد أدى نذارته ، … وقد قضى ما عليه منذ أيام\nإني لأستكثر الدنيا ، وأعظمها … جهلا ولم أرها أهلا لإعظام\nفلو علا بك أقوام مناكبهم ، … حثوا بنعشك إسراعا بأقدام\nفي يوم آخر توديع تودعه … تهدي إلى حيث لا فاد ولا حام\nما الناس إلا كنفس في تقاربهم … لولا تفاوت أرزاق وأقسام\nكم لابن آدم من لهو ، ومن لعب ، … وللحوادث من شد وإقدام\nكم قد نعت لهم الدنيا الحلول بها … لو أنهم سمعوا منها بأفهام\nوكم تحرمت الأيام من بشر … كانوا ذوي قوة فيها وأجسام\nيا ساكن الدار تبنيها ، وتعمرها ، … والدار دار منيات وأسقام\nلا تلعبن بك الدنيا وخدعتها ، … فكم تلاعبت الدنيا بأقوام\nيا رب مقتصد من غير تجربة … ومعتد ، بعد تجريب ، وإحكام\nورب مكتسب بالحكم راميه … ورب مستهدف بالبغي للرامي"},{"id":"diwan-atahiya:127","bookId":"diwan-atahiya","type":"poem","seq":127,"chapter":"قصائد","title":"ألست ترى للدهر نقضا وإبراما ،","page":"","text":"ألست ترى للدهر نقضا وإبراما ، … فهل تم عيش لامرئ فيه أو داما\nلقد أبت الأيام إلا تقلبا … لترفع ذا عاما ، وتخفض ذا عاما\nونحن مع الأيام حيث تقلبت … فترفع أقواما وتخفض أقواما\nفلا توطن الدنيا محلا فإنما … مقامك فيها لا أبا لك أياما"},{"id":"diwan-atahiya:128","bookId":"diwan-atahiya","type":"poem","seq":128,"chapter":"البحر: طويل","title":"أيا رب يا ذا العرش ، أنت حكيم !","page":"","text":"أيا رب يا ذا العرش ، أنت حكيم ! … وأنت بما تخفي الصدور عليم\nفيا رب ! هب لي منك حلما ، فإنني … أرى الحلم لم يندم عليه حليم\nألا إن تقوى الله أكبر نسبة … تسامى بها ، عند الفخار ، كريم\nإذا ما اجتنبت الناس إلا على التقى ، … خرجت من الدنيا وأنت سليم\nأراك امرأ ترجو من الله عفوه ، … وأنت على ما لا يحب مقيم\nفحتى متى يعصى ويعفو إلى متى … تبارك ربي ، إنه لرحيم\nولو قد توسدت الثرى وافترشته … لقد صرت لا يلوي عليك حميم\nتدل على التقوى ، وأنت مقصر ، … أيا من يداوي الناس وهو سقيم\nوإن امرأ ، لا يربح الناس نفعه ، … ولم يأمنوا منه الأذى للئيم\nوإن امرأ ، لم يجعل البر كنزه ، … وإن كانت الدنيا له ، لعديم\nوإن امرأ ، لم يلهه اليوم عن غد … تخوف ما يأتي به لحكيم\nومن يأمن الأيام جهل وقد رأى … لهن صروفا كيدهن عظيم\nفإن منى الدنيا غرور لأهلها … أبى الله أن يبقى عليه نعيم\nوأذللت نفسي اليوم كيما أعزها … غدا ، حيث يبقى العز لي ويدوم\nوللحق برهان وللموت فكرة … ومعتبر للعالمين قديم"},{"id":"diwan-atahiya:129","bookId":"diwan-atahiya","type":"poem","seq":129,"chapter":"البحر: طويل","title":"ألا إنما التقوى هي العز والكرم ،","page":"","text":"ألا إنما التقوى هي العز والكرم ، … وحبك للدنيا هو الذل والعدم\nوليس على عبد تقي نقيصة … إذا صحح التقوى ، وإن حاك أو حجم"},{"id":"diwan-atahiya:130","bookId":"diwan-atahiya","type":"poem","seq":130,"chapter":"البحر: مجزوء الرجز","title":"من سالم الناس سلم","page":"","text":"من سالم الناس سلم … من شاتم الناس شتم\nمن ظلم الناس أسا ، … من رحم الناس رحم\nمن طلب الفضل إلى … غير ذوي الفضل حرم\nمن حفظ العهد وفى ؛ … من أحسن السمع فهم\nمن صدق الله علا … من طلب العلم علم\nمن خالف الرشد غوى … من تبع الغي ندم\nمن لزم الصمت نجا ، … من قال بالخير غنم\nمن عف واكتف زكا ، … من جحد الحق أثم\nمن مسه الضر شكا … من عضه الدهر ألم\nلم يعد حيا رزقه … رزق امرئ حيث قسم"},{"id":"diwan-atahiya:131","bookId":"diwan-atahiya","type":"poem","seq":131,"chapter":"البحر: مديد تام","title":"سكن يبقى له سكن","page":"","text":"سكن يبقى له سكن … ما بهذا يؤذن الزمن !\nنحن في دار يخبرنا ، … عن بلاها ، ناطق لسن\nدار سوء لم يدم فرح … لامرئ فيها ولا حزن\nما نرى من أهلها أحدا ، … لم تغل فيها به الفتن\nعجبا من معشر سلفوا … أي غبن بين غبنوا\nوفروا الدنيا لغيرهم … وابتنوا فيها ، وما سكنوا\nتركوها بعدما اشتبكت … بينهم ، في حبها ، الإحن\nكل حي عند ميتته … حظه من ماله الكفن\nإن مال المرء ليس له … منه ، إلا ذكره الحسن\nما له مما يخلفه ، … بعد إلا فعله الحسن\nفي سبيل الله أنفسنا ، … كلنا بالموت مرتهن"},{"id":"diwan-atahiya:132","bookId":"diwan-atahiya","type":"poem","seq":132,"chapter":"البحر: كامل تام","title":"نهنه دموعك كل حي فان","page":"","text":"نهنه دموعك كل حي فان … واصبر لقرع نوائب الحدثان\nيا داري الحق التي لم أبنها … فيما أشيده من البنيان\nكيف العزاء ولا محالة إنني … يوما ، إليك ، مشي ع إخواني\nنعشا يكفكفه الرجال ، وفوقه … جسد يباع بأوكس الأثمان\nلولا الإله وإن قلبي مؤمن … والله غير مضيع إيماني\nلظننت ، أو أيقنت عند منيتي ، … أن المصير إلى محل هوان\nفبنور وجهك يا إله مراحم … زحزح إليك ، عن السعير ، مكاني\nوامنن علي بتوبة ترضى بها … يا ذا العلى والمن والإحسان"},{"id":"diwan-atahiya:133","bookId":"diwan-atahiya","type":"poem","seq":133,"chapter":"البحر: وافر تام","title":"أيا من بين باطية ودن","page":"","text":"أيا من بين باطية ودن … وعود في يدي غاو مغن\nإذا لم تنه نفسك عن هواها … وتحسن صونها ، فإليك عني\nفإن اللهو والملهى جنون ، … ولست من الجنون وليس مني\nوأي قبيح أقبح من لبيب … يرى متطربا في مثل سني\nإذا ما لم يتب كهل لشيب ، … فليس بتائب ما عاش ، ظني"},{"id":"diwan-atahiya:134","bookId":"diwan-atahiya","type":"poem","seq":134,"chapter":"البحر: مجزوء الكامل","title":"أين القرون بنو القرون","page":"","text":"أين القرون بنو القرون … وذوو المدائن والحصون\nوذوو التجبر في المجا … لس ، والتكبر في العيون\nكانوا اللوك ، فأيهم … لم يفنه ريب المنون\nأو أيهم لم يلف ، في … دار البلى علق الرهون\nولو علوا في عيشة ، … ليست لأنفسهم بدون\nصاروا حديثا بعدهم ، … إن الحديث لذو شجون\nوالدهر دائبة عجا … ئب صرفه ، جم الفنون"},{"id":"diwan-atahiya:135","bookId":"diwan-atahiya","type":"poem","seq":135,"chapter":"البحر: كامل تام","title":"كم من أخ لك نال سلطانا ،","page":"","text":"كم من أخ لك نال سلطانا ، … فكأنه ليس الذي كانا\nما أسكر الدنيا لصاحبها … وأضرها للعقل أحيانا\nدار لها شبه ملبسة ، … تدع الصحيح العقل سكرانا"},{"id":"diwan-atahiya:136","bookId":"diwan-atahiya","type":"poem","seq":136,"chapter":"البحر: خفيف تام","title":"أين من كان قبلنا أين أينا","page":"","text":"أين من كان قبلنا أين أينا … من أناس كانوا جمالا ورزينا\nإن دهرا أتى عليهم ، فأفنى … منهم الجمع سوف يأتي علينا\nخدعتنا الآمال حتى طلبنا … وجمعنا لغيرنا وسعينا\nوابتنينا ، وما نفكر في الده … ر وفي صرفه ، غداة ابتنينا\nوابتغينا من المعاش فضولا ، … لو قنعنا بدونها لاكتفينا\nولعمري لنمضين ولا نمضي … بشيء منها إذا ما مضينا\nوافترقنا في المقدرات ، وسوى … الله في الموت بيننا واستوينا\nكم رأينا من ميت كان حيا ، … ووشيكا يرى بنا ما رأينا\nما لنا نأمل المنايا كأنا … لا نراهن يهتدين إلينا\nعجبا لامرىء تيقن أن ال … الموت حقا فقر بالعيش عينا"},{"id":"diwan-atahiya:137","bookId":"diwan-atahiya","type":"poem","seq":137,"chapter":"البحر: مجزوء الكامل","title":"إن الزمان ولو يلين","page":"","text":"إن الزمان ولو يلين … ن لأهله ، لمخاشن"},{"id":"diwan-atahiya:138","bookId":"diwan-atahiya","type":"poem","seq":138,"chapter":"البحر: هزج","title":"أيا واها لذكر الله ،","page":"","text":"أيا واها لذكر الله ، … يا واها له ، واها !\nلقد طيب ذكر الل … بالتسبيح أفواها\nفيا أنتن من زبل ، … على زبل ، إذا تاها\nأرى قوما يتيهون ، … بهاما رزقوا جاها"},{"id":"diwan-atahiya:139","bookId":"diwan-atahiya","type":"poem","seq":139,"chapter":"البحر: خفيف تام","title":"إنما الشيب ، لابن آدم ، ناع","page":"","text":"إنما الشيب ، لابن آدم ، ناع … قام في عارضيه ثم نعاه"},{"id":"diwan-atahiya:140","bookId":"diwan-atahiya","type":"poem","seq":140,"chapter":"البحر: طويل","title":"إذا ما سألت المرء هنت عليه ،","page":"","text":"إذا ما سألت المرء هنت عليه ، … يراك حقيرا من رغبت إليه\nفلا تسألن المرء إلا ضرورة ، … ووفر عليه كل ذات يديه\nومن جاء يبغي ما لديك فأرضه … بجهدك ، واترك ما يكون لديه"},{"id":"diwan-atahiya:141","bookId":"diwan-atahiya","type":"poem","seq":141,"chapter":"البحر: مجزوء الكامل","title":"ألمرء منظور إليه ،","page":"","text":"ألمرء منظور إليه ، … مادام يرجى ما لديه\nمن كنت تبغي أن تكو … ن ، الدهر ، ذا فضل عليه\nفابذل له ما في يديك … ك وغض عما في يديه"},{"id":"diwan-atahiya:142","bookId":"diwan-atahiya","type":"poem","seq":142,"chapter":"البحر: مجزوء الكامل","title":"المرء يخدعه مناه ،","page":"","text":"المرء يخدعه مناه ، … والدهر يسرع في بلاه\nيا ذا الهوى مه لا تكن … ممن تعبده هواه !\nواعلم بأن المرء مر … تهن بما كسبت يداه\nكم من أخ لك لا ترى … متصرفا ، فيما تراه\nأمسى قريب الدار في … الأجداث قد شحطت نواه\nقد كان مغترا بيو … م وفاته ، حتى أتاه\nالناس في غفلاتهم ، … والموت دائرة رحاه\nفالحمد لله الذي … ويهلك ما سواه"},{"id":"diwan-atahiya:143","bookId":"diwan-atahiya","type":"poem","seq":143,"chapter":"البحر: كامل تام","title":"قل للذين تشبهوا بذوي التقى :","page":"","text":"قل للذين تشبهوا بذوي التقى : … لا يلعبن بنفسه متشبه\nهيهات لا يخفى التقى من ذي التقى … هيهات لا يخفى امرؤ متآله\nإن القلوب إذا طوت أسرارها ، … أبدت لك الأسرار منها الأوجه"},{"id":"diwan-atahiya:144","bookId":"diwan-atahiya","type":"poem","seq":144,"chapter":"البحر: طويل","title":"تصبر عن الدنيا ودع كل تائه","page":"","text":"تصبر عن الدنيا ودع كل تائه … مطيع هوى ، يهوي به في المهامه\nدع الناس والدنيا فبين مكالب … عليها بأنياب ، وبين مشافه\nومن لم يحاسب نفسه في أموره … يقع في عظيم مشكل متشابه\nوما فاز أهل الفضل إلا بصبرهم … عن الشهوات ، واحتمال المكاره"},{"id":"diwan-atahiya:145","bookId":"diwan-atahiya","type":"poem","seq":145,"chapter":"البحر: مديد تام","title":"إنما الذنب على من جناه ،","page":"","text":"إنما الذنب على من جناه ، … لم يضر قبل جهولا سواه\nفسد الناس جميعا ، فأمسى … خيرهم من كف عنا أذاه"},{"id":"diwan-atahiya:146","bookId":"diwan-atahiya","type":"poem","seq":146,"chapter":"البحر: متقارب تام","title":"ألا يا بني آدم استنبهوا ،","page":"","text":"ألا يا بني آدم استنبهوا ، … أما قد نهيتم فلا تنتهوا\nأيا عجبا من ذوي الاعتبا … ر ما منهم اليوم مستنبه\nطغى الناس حتى رأيت اللبيب … في غي طغيانه يعمه"},{"id":"diwan-atahiya:147","bookId":"diwan-atahiya","type":"poem","seq":147,"chapter":"البحر: طويل","title":"وإني لمشتاق إلى ظل صاحب ،","page":"","text":"وإني لمشتاق إلى ظل صاحب ، … يروق ويصفو ، إن كدرت عليه\nعذيري من الإنسان لا إن جفوته … صفا لي ولا إن كنت طوع يديه"},{"id":"diwan-atahiya:148","bookId":"diwan-atahiya","type":"poem","seq":148,"chapter":"البحر: وافر تام","title":"أرى الدنيا لمن هي في يديه","page":"","text":"أرى الدنيا لمن هي في يديه … عذابا ، كلما كثرت لديه\nتهين المكرمين لها بصغر … وتكرم كل من هانت عليه\nإذا استغنيت عن شيء ، فدعه … وخذ ما أنت محتاج إليه"},{"id":"diwan-atahiya:149","bookId":"diwan-atahiya","type":"poem","seq":149,"chapter":"البحر: خفيف تام","title":"أنا بالله وحده وإليه","page":"","text":"أنا بالله وحده وإليه … إنما الخير كله في يديه\nأحمد الله وهو ألهمني الحمد … د على المن والمزيد لديه\nكم زمان بكيت منه قديما … ثم لما مضى بكيت عليه"},{"id":"diwan-atahiya:150","bookId":"diwan-atahiya","type":"poem","seq":150,"chapter":"البحر: كامل تام","title":"نام الخلي لأنه خلو","page":"","text":"نام الخلي لأنه خلو … عمن يؤرق عينه الشجو\nما إن يطيب لذي الرعاية لل … أيام لا لعب ، ولا لهو\nإذ كان يسرف في مسرته ، … فيموت ، من أعضائه جزو\nوإذا المشيب رمى بوهنته … وهت القوى وتقارب الخطو\nوإذا استحال بأهله زمن ، … كثر القذى ، وتكدر الصفو"},{"id":"diwan-atahiya:151","bookId":"diwan-atahiya","type":"poem","seq":151,"chapter":"البحر: طويل","title":"أيا عجبا للناس في طول ما سهوا","page":"","text":"أيا عجبا للناس في طول ما سهوا … وفي طول ما اغتروا وفي طول ما لهوا\nيقولون نرجو الله ثم افتروا به … ولو أنهم يرجون خافوا كما رجوا\nتصابى رجال ، من كهول وجلة ، … إلى اللهو ، حتى لا يبالون ما أتوا\nفيا سوءة للشيب إذ صار أهله … إذا هيجتهم للصبا صبوة ، صبوا\nأكب بنو الدنيا عليها ، وإنهم … لتنهاهم الأيام عنها لو انتهوا\nمضى قبلنا قوم قرون نعدهم … ونحن وشيكا سوف نمضي كما\nألا في سبيل الله أي ندامة … نوت ، كما مات الألى ، كلما خلوا\nولم نتزود للمعاد وهوله ، … كزاد الذين استعصموا الله واتقوا\nألا أين أين الجامعون لغيرهم ، … وما غلبوا غشما عليه وما احتووا\nرأيت بني الدنيا ، إذا ما سموا بها ، … هوت بهم الدنيا على قدر ما سموا\nوكل بني الدنيا ، ولو تاه تائه ، … قد اعتدلوا في النقص والضعف واستووا\nولم أر مثل الصدق أحلى لوحشة … ولا مثل إخوان الصلاح إذا اتقوا"},{"id":"diwan-atahiya:152","bookId":"diwan-atahiya","type":"poem","seq":152,"chapter":"البحر: وافر تام","title":"كأن الأرض قد طويت عليا ،","page":"","text":"كأن الأرض قد طويت عليا ، … وقد أخرجت مما في يديا\nكأني يوم يحثو الترب قومي ، … مهيلا ، لم أكن في الناس حيا\nكأن القوم قد دفنوا وولوا … وكل غير ملتفت إليا\nكأن قد صرت منفردا ، وحيدا ، … ومرتهنا ، هناك ، بما لديا\nكأن الباكيات علي ، يوما ، … وما يغني البكاء علي شيا\nذكرت منيتي ، فبكيت نفسي ، … ألا أسعد أخيك ، أي أخيا !"},{"id":"diwan-atahiya:153","bookId":"diwan-atahiya","type":"poem","seq":153,"chapter":"البحر: خفيف تام","title":"إن أسوا يوم ي مر عليا ،","page":"","text":"إن أسوا يوم ي مر عليا ، … يوم لا رغبة تكون إليا\nكم تغر الدنيا وكم يجد ال … الإنسان فيها شيئا ويحرم شيئا\nتنشر الحادثات طورا ، وتطوي ، … إنما الحادثات نشرا ، وطيبا\nوطباع الأسنان مختلفات … رب وعر الأخلاق سهل المحيا"},{"id":"diwan-atahiya:154","bookId":"diwan-atahiya","type":"poem","seq":154,"chapter":"البحر: بسيط تام","title":"إن السلامة أن نرضى بما قضيا ،","page":"","text":"إن السلامة أن نرضى بما قضيا ، … ليسلمن ، بإذن الله ، من رضيا\nالمرء يأمل ، والآمال كاذبة ، … والمرء تصحبه الآمال ما بقيا\nيا رب باك على ميت وباكية … لم يلبثا بعد ذاك الميت أن بكيا\nورب ناع نعى حينا أحبته … ما زال ينعى إلى أن قيل قد نعيا\nعلمي بأني أذوق الموت نغص لي … طيب الحياة ، فما تصفوا الحياة ليا\nكم من أخ تغتذي دود التراب به ، … وكان صبا بحلو العيش ، مغتذيا\nيبلى مع الميت ذكر الذاكرين له ، … من غاب غيبة من لا يرتجى نسيا\nمن مات مات رجاء الناس منه فو … لوه الجفاء ، ومن لا يرتجى جفيا\nإن الرحيل عن الدنيا ليزعجني ، … إن لم يكن رائحا بي كان مغتديا\nالحمد لله ، طوبى للسعيد ، ومن … لم يسعد الله بالتقوى ، فقد شقيا\nكم غافل عن حياض الموت في لعب ، … يمسي ، ويصبح ركابا لما هويا\nومنقض ما تراه العين منقطع … ما كل شيء بدا إلا لينقضيا"},{"id":"diwan-atahiya:155","bookId":"diwan-atahiya","type":"poem","seq":155,"chapter":"البحر: طويل","title":"ركنا إلى الدنيا الدنئة ضلة","page":"","text":"ركنا إلى الدنيا الدنئة ضلة … وكشفت الأطماع منا المساويا\nوإنا لنرمى كل يوم بعبرة ، … نراها ، فما تزداد إلا تماديا\nنسر بدار أورثتنا تضاغنا … عليها ، ودار أورثتنا تعاديا\nإذا المرء لم يلبس ثيابا من التقى … تقلب عريانا وإن كان كاسيا\nأخي ! كن على يأس من الناس كلهم … جميعا وكن ما عشت لله راجيا\nألم تر أن الله يكفي عباده … فحسب عباد الله بالله كافيا\nوكم من هناة ، ما عليك ، لمستها … من الناس يوما أو لمست الأفاعيا\nأخي ! قد أبى بخلي وبخلك أن يرى … لذي فاقة مني ومنك مؤاسيا\nكلانا بطين جنبه ، ظاهر الكسى ، … وفي الناس من يمسي ويصبح عاريا\nكأني خلقت للبقاء مخلدا … وأن مدة الدنيا له ليس ثانيا\nإلى الموت إلا أن يكون لمن ثوى … من الخلق طرا ، حيثما كان لاقيا\nحسمت المنى يا موت حسما مبرحا … وعلمت يا موت البكاء البواكيا\nومزقتنا ، يا موت ، كل ممزق ، … وعرفتنا يا موت منك الدواهيا\nألا يا طويل السهو أصبحت ساهيا … وأصبحت مغترا ، وأصبحت لاهيا\nأفي كل يوم نحن نلقى جنازة … وفي كل يوم منك نسمع مناديا\nوفي كل يوم منك نرثي لمعول … وفي كل يوم نحن نسعد باليا\nألا أيها الباني لغير بلاغة ، … ألا لخراب الدهر أصبحت بانيا\nألا لزوال العمر أصبحت بانيا ؛ … وأصبحت مختالا ، فخورا ، مباهيا\nكأنك قد وليت عن كل ما ترى ، … وخلفت من خلفته عنك ساليا"}]};